 assert(s.daily&&/^\d{4}-\d{2}-\d{2}$/.test(s.daily.date)&&typeof s.daily.gift==="boolean"&&int(s.daily.contest,3)&&int(s.daily.repeats,10),"每日记录异常");
 assert(s.contest&&THEMES.some(t=>t.id===s.contest.theme)&&int(s.contest.entries)&&s.contest.records,"评选记录异常");
 const validSlot=(id,slot)=>id===null||(Number.isInteger(id)&&s.owned.includes(id)&&(["dress","top","bottom"].includes(FASHION[id].type)?slot===0:FASHION[id].type==="shoes"?slot===1:slot===2));
 for(const theme of THEMES){const x=s.contest.records[theme.id];assert(x&&Array.isArray(x.outfit)&&x.outfit.length===3&&x.outfit.every(validSlot)&&int(x.best,300)&&int(x.attempts)&&Array.isArray(x.claimed)&&unique(x.claimed)&&x.claimed.every(v=>[150,215,260].includes(v)&&x.best>=v),"搭配或评选领奖数据异常");}
