 for(const o of [s.activeOrder,s.lastDelivery])if(o){assert(o&&typeof o==="object"&&Number.isInteger(o.item)&&FASHION[o.item],"顾客订单记录异常");if(!Object.hasOwn(o,"demand"))o.demand={variant:0,key:null};const d=o.demand;assert(d&&Number.isSafeInteger(d.variant)&&d.variant>=0&&d.variant<=MAX&&(d.key===null||typeof d.key==="string"&&/^need-\d+-\d+-\d+$/.test(d.key)),"顾客需求快照异常");}
 assert(typeof s.loopClaimed==="boolean"&&Array.isArray(s.history)&&s.history.length<=30&&s.history.every(h=>typeof h.text==="string"&&h.text.length<160&&Number.isFinite(h.at)),"试玩记录异常");
