 const mallVersion=s.mall.version; if(mallVersion===1)s.economyVersion=1;else if(!Object.hasOwn(s,"economyVersion"))s.economyVersion=2; assert([1,2].includes(s.economyVersion),"商城经济版本异常");
 s.mall=Mall.validate(s.mall,s);
