/* V41: mobile scroll cue for long workbench, outfit diary, and backpack pages. */
function scrollCueMarkup(view){const labels={work:'向下滑动查看样衣与操作',contest:'向下滑动查看穿搭作品',catalog:'向下滑动查看更多服饰'};const label=labels[view]||'向下滑动查看更多';return '<button class="scroll-cue scroll-cue-'+view+'" data-action="scroll-cue" type="button" aria-label="'+label+'"><span class="scroll-cue-arrow" aria-hidden="true">⌄</span><span>'+label+'</span></button>';}
function scrollCueHost(){const view=$('#view');if(!view)return null;return document.scrollingElement||document.documentElement;}function mountScrollCue(){const view=$('#view'),cue=view?.querySelector('[data-action="scroll-cue"]');if(!view||!cue)return;view.__scrollCueCleanup?.();const host=scrollCueHost();if(!host)return;const isDocument=host===document.scrollingElement||host===document.documentElement;const metrics=()=>isDocument?{top:window.scrollY||document.documentElement.scrollTop||document.body.scrollTop||0,client:window.innerHeight,height:Math.max(document.documentElement.scrollHeight,document.body.scrollHeight)}:{top:host.scrollTop,client:host.clientHeight,height:host.scrollHeight};const update=()=>{const m=metrics(),actions=ui.view==='work'?view.querySelector('.work-actions'):null,rect=actions?.getBoundingClientRect(),actionsVisible=Boolean(rect&&rect.top>=0&&rect.bottom<=window.innerHeight-8&&m.top>24),showInitialWorkCue=ui.view==='work'&&m.top<=24&&m.height>m.client+12;cue.hidden=showInitialWorkCue?false:(actionsVisible||!(m.height>m.client+12)||m.top+m.client>=m.height-18);};const onScroll=()=>update();const onCueClick=e=>{e.preventDefault();e.stopPropagation();scrollCueAction();};cue.addEventListener('click',onCueClick,true);host.addEventListener('scroll',onScroll,{passive:true});if(isDocument)window.addEventListener('scroll',onScroll,{passive:true});window.addEventListener('resize',update,{passive:true});view.__scrollCueCleanup=()=>{cue.removeEventListener('click',onCueClick,true);host.removeEventListener('scroll',onScroll);if(isDocument)window.removeEventListener('scroll',onScroll);window.removeEventListener('resize',update);};requestAnimationFrame(update);}function scrollCueAction(){const host=scrollCueHost();if(!host)return;const isDocument=host===document.scrollingElement||host===document.documentElement;const m=isDocument?{top:window.scrollY||document.documentElement.scrollTop||document.body.scrollTop||0,client:window.innerHeight,height:Math.max(document.documentElement.scrollHeight,document.body.scrollHeight)}:{top:host.scrollTop,client:host.clientHeight,height:host.scrollHeight};const next=Math.min(Math.max(0,m.height-m.client),m.top+Math.max(220,Math.round(m.client*.78)));if(isDocument){window.scrollTo({top:next,behavior:'auto'});document.documentElement.scrollTop=next;document.body.scrollTop=next;}else{host.scrollTo({top:next,behavior:'auto'});host.scrollTop=next;}}function scrollCueAction(){const host=scrollCueHost();if(!host)return;const isDocument=host===document.scrollingElement||host===document.documentElement;const m=isDocument?{top:window.scrollY||document.documentElement.scrollTop||document.body.scrollTop||0,client:window.innerHeight,height:Math.max(document.documentElement.scrollHeight,document.body.scrollHeight)}:{top:host.scrollTop,client:host.clientHeight,height:host.scrollHeight};const next=Math.min(Math.max(0,m.height-m.client),m.top+Math.max(220,Math.round(m.client*.78)));if(isDocument){window.scrollTo({top:next,behavior:'auto'});document.documentElement.scrollTop=next;document.body.scrollTop=next;}else{host.scrollTo({top:next,behavior:'auto'});host.scrollTop=next;}requestAnimationFrame(()=>{const view=$('#view'),cue=view?.querySelector('[data-action="scroll-cue"]');if(cue)cue.hidden=true;});}
function render(){document.body.dataset.view=ui.view;hud();nav();renderGuide();$("#view").classList.toggle("pixel-workshop",ui.view==="work");$("#view").innerHTML=({map:renderMap,work:renderWork,customer:renderCustomer,catalog:renderCatalog,contest:renderContest,profile:renderProfile,community:renderCommunity,home:renderHome,ranking:()=>FashionRankUI.render()})[ui.view]();if(["catalog","contest"].includes(ui.view))$("#view").insertAdjacentHTML("beforeend",scrollCueMarkup(ui.view));mountScrollCue();if(ui.view==="work")$("#view").insertAdjacentHTML("afterbegin",renderStoryMiniCard());if(ui.view==="customer"&&game.state.activeOrder){$(".customer-layout>aside")?.remove();const end=$(".customer-layout>section");end?.insertAdjacentHTML("beforeend",`<button class="text-btn mobile-cancel" data-action="cancel-order">取消订单 · 退还材料费</button>`);}if($("#sketch"))setupSketch();warning();syncNotices();syncSigninNotice();mountShopScene();syncAudioToggle();if(ui.view==="ranking")FashionRankUI.mount();}
function itemModal(id){if(game.state.owned.includes(id))game.markSeen(id);const s=game.state,x=FASHION[id],owned=s.owned.includes(id),bp=s.blueprints.includes(id);openModal(x.name,`<div class="detail-art">${photo(id)}</div><div class="row">${stars(x.stars)}<span class="pill ${owned?"green":"pink"}">${owned?"永久拥有":"尚未拥有"}</span></div><div class="detail-rows"><div class="row"><span>品类与颜色</span><b>${TYPE_NAMES[x.type]} / ${x.color}</b></div><div class="row"><span>主题标签</span><b>${x.tags.join(" / ")}</b></div><div class="row"><span>来源</span><b>${STORES[x.store].name} · 研发后制衣</b></div><div class="row"><span>版型条件</span><b>${bp?"已解锁":game.researchReason(id)||"可在工作台研发"}</b></div></div><p class="modal-text">收藏不消耗样衣；提交设计样衣与顾客交付不会撤销你的衣橱所有权。</p><div class="modal-actions">${owned?(!s.discoveryClaims.includes(id)?`<button class="btn sage" data-action="claim-discovery" data-id="${id}">领取首次收藏 · ${x.stars===5?15:5}券${noticeSlot("item-reward:"+id)}</button>`:`<button class="btn light" data-action="close">首次奖励已领取</button>`):bp?`<button class="btn" data-action="take-order" data-id="${id}">去为顾客制衣</button><button class="btn outline" data-action="buy" data-id="${id}">补缺 · ${x.price}券</button>`:`<button class="btn" data-action="recipe" data-id="${id}">去研发版型${icon("arrow")}</button>`}</div>`);}
function storeModal(id){const shop=game.state.shops[id],def=STORES[id];if(!shop.open)return toast("先完成开业条件");const base=def.base+def.step*(shop.level-1),business=shop.business.length*.2,staff=shop.staff?.15:0,sets=game.state.setClaims.length*.05;openModal(def.name,`<p class="modal-text">秒收入由真实店铺状态计算，升级前会先结算旧收入。试玩的升级费用与门槛已压缩。</p><div class="detail-rows"><div class="row"><span>基础收入 · LV ${shop.level}</span><b>${base}元/秒</b></div><div class="row"><span>首制营业款式 · ${shop.business.length}款</span><b>+${Math.round(business*100)}%</b></div><div class="row"><span>店员派驻</span><b>+${Math.round(staff*100)}%</b></div><div class="row"><span>套装收藏</span><b>+${Math.round(sets*100)}%</b></div><div class="row"><span>总收入</span><b>${fmt(game.shopIncome(id))}元/秒</b></div></div><p class="modal-text">公式：基础收入 ×（1 + 营业款式 + 店员 + 套装加成）</p><div class="modal-actions"><button class="btn sage" data-action="nav" data-view="work">去研发版型</button><button class="btn light" data-action="nav" data-view="customer">去顾客制衣</button></div>`);}
function receipt(result){const x=FASHION[result.item],autoLook={3:1,10:4,16:3,21:4}[result.item]||1;if(result.firstCraft)try{game.updateProfile({dressLook:autoLook});}catch(e){}openModal(result.firstCraft?"你的设计，成为了新衣":"顾客交付完成",`<p class="success-title">${result.newItem?"收藏 +1":result.firstCraft?"首制完成":"心意已送达"}</p><div class="detail-art">${photo(x.id)}</div><div class="row"><b>${x.name}</b>${stars(x.stars)}</div><div class="success-rewards"><span>+${fmt(result.coins)}元</span><span>+${result.vouchers}服饰券</span>${result.firstCraft?"<span>店铺业务收入+20%</span><span>已自动试穿</span>":""}</div><p class="modal-text">${result.newItem?"这件服装已永久加入衣橱。已自动试穿，可继续发布穿搭日记。":"已拥有的服装不会被交付扣除。重复奖励每日最多10次。"}</p><div class="modal-actions"><button class="btn sage" data-action="profile-dress">立即试穿${icon("arrow")}</button><button class="btn" data-action="ugc-compose">发布穿搭日记${icon("arrow")}</button><button class="btn light" data-action="nav" data-view="customer">继续接待</button></div>`);}
function settings(){openModal("试玩与存档",`<p class="modal-text">时光百货 · 手游试玩 V0.30<br>2家店 / 25件服装 / 5套收藏 / 3个评选主题。<br>手游独立存档，不改动桌面版；可导入原V0.5闭环进度。<br>节奏已压缩，非原作完整数值；无真实支付、广告与联网玩家。${storageOK?"":"<br>自动保存不可用，请导出备份。"}</p><button class="settings-action" data-action="mobile-help">手机操作指引<small>点按/拖动合成，自由触屏草图，底部五页切换</small></button><button class="settings-action" data-action="export">导出手游进度<small>保存经营、样衣、版型、服装、草图与评选记录</small></button><button class="settings-action" data-action="import">导入闭环进度<small>接受手游版及原V0.5闭环存档，失败不覆盖</small></button><button class="settings-action" data-action="demo-wait">试玩加速：模拟离线30分钟<small>明确的测试功能，不等同真实离线经过30分钟</small></button><button class="settings-action" data-action="journal">设计手记<small>查看开业、研发、制作与评选反馈</small></button><button class="settings-action" data-action="reset-request">重新开始手游试玩<small>二次确认；仅重置手游版进度</small></button><small id="modal-save-status">${storageOK?"此浏览器自动保存":"请导出进度备份"}</small>`);}
function guideAction(){const m=mission();if(m.index===5&&!game.state.loopClaimed){game.claimLoop();toast("第一轮闭环完成：+2,500元、25券与20体力");return;}if(m.index===1){ui.recipe=3;go("work",{recipe:3});return;}if(m.index===2){ui.orderList=true;ui.orderTab="offers";ui.orderType="all";go("customer");return;}if(m.index===5)ui.recipe=game.nextRecipe()??3;go(m.view);if(m.index===0){requestAnimationFrame(()=>$(".store-card:not(.locked)")?.scrollIntoView({behavior:"smooth",block:"center"}));toast("点击服装商店的升级按钮，先升到2级");}if(m.index===3)itemModal(3);}
