function mobilePatterns(){openModal("选择研发版型",`<p class="modal-text">选择下一份设计。研发3张开放G2，8张开放G3。版型不直接授予成衣，研发后还需接待顾客。</p><div class="pattern-list">${ORDER.map(id=>{const x=FASHION[id],known=game.state.blueprints.includes(id),why=game.researchReason(id);return `<button class="pattern-button ${ui.recipe===id?"active":""}" data-action="blueprint-detail" data-id="${id}"><span class="pattern-garment-icon" data-fashion-id="${id}">${photo(id)}</span><span><b>${x.name}</b><small>${known?"已研发 · 可接待顾客":why||CHAINS[x.chain].name+" T"+(x.tier+1)}</small></span>${icon(known?"check":why?"lock":"arrow")}</button>`;}).join("")}</div>`);}
function mobileRewards(){const s=game.state,theme=THEMES.find(x=>x.id===s.contest.theme),rec=s.contest.records[theme.id],score=game.score();openModal("评选反馈 · "+theme.name,`<div class="row"><b>当前搭配预估</b><b>${score.total} / 300</b></div><div class="detail-rows">${["均衡搭配","主件表现","主题契合"].map((name,i)=>`<div class="row"><span>${name}</span><b>${score.judges[i]} / 100</b></div>`).join("")}</div><p class="modal-text">最好成绩 ${rec.best}分 · 每个主题里程碑只领一次<br>印章用于高定研发，体力用于合成，服饰券用于补缺。</p>${[150,215,260].map((n,i)=>`<div class="reward-row"><span class="reward-score">${n}</span><span><b>${["花园新秀","人气设计师","闪耀之星"][i]}</b><small>${[15,25,40][i]}券 · ${[5,10,15][i]}印章 · 体力</small></span><button class="btn small ${rec.best>=n?"sage":"light"}" data-action="claim-contest" data-threshold="${n}" ${rec.best<n||rec.claimed.includes(n)?"disabled":""}>${rec.claimed.includes(n)?"已领":"领取"}${noticeSlot("contest-reward:"+theme.id+":"+n)}</button></div>`).join("")}<button class="btn full light" data-action="nav" data-view="work">带着反馈，继续研发</button>`);}
function mobileRanking(){const theme=THEMES.find(x=>x.id===game.state.contest.theme),best=game.state.contest.records[theme.id].best;const ranks=[{name:"薇薇安",score:279},{name:"林夕",score:253},{name:"苏珊",score:228},{name:"米娅",score:195},...(best?[{name:"艾米 · 你",score:best,me:true}]:[])].sort((a,b)=>b.score-a.score||Number(b.me)-Number(a.me));openModal("本地展示榜",`<p class="modal-text">${theme.name} · 预设角色模拟榜，不是联网玩家排行</p>${ranks.map((x,i)=>`<div class="ranking-row ${x.me?"me":""}"><span class="rank">${i+1}</span><span>${x.name}</span><strong>${x.score}</strong></div>`).join("")}`);}
function mobileHelp(){openModal("手机试玩指引",`<ol class="mobile-help-list"><li>经营：升级女装店到2级，营业金需要点「收取」。</li><li>工作台：先点1件再点9件，或把1件拖到9件上；10件同款升阶。</li><li>研发「春日絮语」，从经营页的「制衣订单」接待顾客。</li><li>选择上装、粉色；用手指画两笔，或点辅助草图；选对应成衣交付。</li><li>图鉴中领取首获奖励。服装永久保留。</li><li>评选中一键推荐、提交评选，领取里程碑；回经营领首轮奖励。</li></ol><p class="modal-text">制衣订单在经营页右侧入口；底部四个导航随时切页。蓝图、补给和奖励从底部弹出，右上角关闭。图鉴人物是预制整套立绘，不是自由分层换装。原型没有真实付费与联网数据。</p><button class="btn full" data-action="close">开始体验</button>`);}
function setupSketch(){const canvas=$("#sketch"),box=canvas.getBoundingClientRect(),dpr=Math.min(2,window.devicePixelRatio||1);canvas.width=Math.round(box.width*dpr);canvas.height=Math.round(box.height*dpr);const ctx=canvas.getContext("2d"),w=canvas.width,h=canvas.height,order=game.state.activeOrder;const colors={黄色:"#bf9237",蓝色:"#5a899f",粉色:"#b66b80",白色:"#a69d91",黑色:"#403b44",紫色:"#8e74b3",棕色:"#907263",金色:"#ae8c49"};let points=[],drawing=false;const norm=e=>{const r=canvas.getBoundingClientRect();return [Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))];};const line=(pts)=>{if(!pts.length)return;ctx.beginPath();ctx.moveTo(pts[0][0]*w,pts[0][1]*h);for(const p of pts.slice(1))ctx.lineTo(p[0]*w,p[1]*h);ctx.stroke();};const paint=()=>{ctx.clearRect(0,0,w,h);ctx.save();ctx.strokeStyle="#b9a99288";ctx.fillStyle="#ebdcc120";ctx.lineWidth=dpr;ctx.setLineDash([4*dpr,4*dpr]);ctx.beginPath();ctx.ellipse(w*.5,h*.16,w*.052,h*.06,0,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.beginPath();ctx.moveTo(w*.465,h*.225);ctx.lineTo(w*.36,h*.25);ctx.lineTo(w*.26,h*.52);ctx.lineTo(w*.3,h*.54);ctx.lineTo(w*.41,h*.35);ctx.lineTo(w*.43,h*.52);ctx.lineTo(w*.37,h*.88);ctx.lineTo(w*.43,h*.9);ctx.lineTo(w*.5,h*.65);ctx.lineTo(w*.57,h*.9);ctx.lineTo(w*.63,h*.88);ctx.lineTo(w*.57,h*.52);ctx.lineTo(w*.59,h*.35);ctx.lineTo(w*.7,h*.54);ctx.lineTo(w*.74,h*.52);ctx.lineTo(w*.64,h*.25);ctx.lineTo(w*.535,h*.225);ctx.stroke();ctx.setLineDash([]);ctx.strokeStyle=colors[order.color]||"#b66b80";ctx.lineWidth=2.5*dpr;ctx.lineCap="round";ctx.lineJoin="round";for(const pts of order.strokes)line(pts);line(points);ctx.restore();};paint();
canvas.addEventListener("pointerdown",e=>{if(e.isPrimary===false)return;drawing=true;points=[norm(e)];canvas.setPointerCapture(e.pointerId);e.preventDefault();});canvas.addEventListener("pointermove",e=>{if(!drawing)return;if(points.length<128)points.push(norm(e));paint();e.preventDefault();});const finish=e=>{if(!drawing)return;drawing=false;if(points.length<2)points.push([Math.min(1,points[0][0]+.003),Math.min(1,points[0][1]+.003)]);const stroke=points;points=[];try{game.stroke(stroke);}catch(err){toast(err.message);}if(canvas.hasPointerCapture(e.pointerId))canvas.releasePointerCapture(e.pointerId);};canvas.addEventListener("pointerup",finish);canvas.addEventListener("pointercancel",()=>{drawing=false;points=[];paint();});sketch={canvas,paint};}
/* Dedicated board input controller: no global post-drag tap blackout. */
function boardFeedback(from,to){
 const a=game.state.board[from],b=game.state.board[to];if(!a)return;
 const source={...a},target=b?{...b}:null;
 try{
  const result=game.move(from,to);ui.selected=null;render();
  if(!target)toast('样衣已移动到空格');
  else if(result.merge){const spare=game.state.board[from]?.n||0;toast(`合成升阶：获得T${result.t+1}样衣${spare?'，原格保留'+spare+'件余数':''}`);}
  else{const item=game.state.board[to];toast(item.t===5?`同款已堆叠为${item.n}/10件 · T6为最高阶`:`同款已合并为${item.n}/10件，还差${10-item.n}件升阶`);}
 }catch(err){ui.selected=game.state.board[from]?from:null;render();toast(err.message);}
}
function boardActivate(index){
 if(ui.selected===null){if(game.state.board[index])ui.selected=index;render();return;}
 if(ui.selected===index){ui.selected=null;render();return;}
 boardFeedback(ui.selected,index);
}
let boardGesture=null,boardNativeClick=null,boardGhost=null;
function clearBoardGesture(){
 if(boardGesture){const {cell,pointerId}=boardGesture;boardGesture=null;if(cell.isConnected&&cell.hasPointerCapture?.(pointerId)){try{cell.releasePointerCapture(pointerId);}catch(e){}}}
 boardGhost?.remove();boardGhost=null;document.querySelectorAll('.cell.dragging,.cell.drop-ready').forEach(el=>el.classList.remove('dragging','drop-ready'));
}
function ignoreBoardClick(event){
 if(event.detail===0)return false; // keyboard / accessible programmatic activation
 if(!boardNativeClick)return false;
 const expected=boardNativeClick;boardNativeClick=null;
 return performance.now()-expected.at<1200&&(event.pointerId===undefined||event.pointerId===expected.pointerId);
}
document.addEventListener('pointerdown',event=>{
 const cell=event.target.closest('.cell');if(!cell||event.button!==0||event.isPrimary===false||modal.open)return;
 clearBoardGesture();boardNativeClick=null;
 boardGesture={index:Number(cell.dataset.index),cell,pointerId:event.pointerId,x:event.clientX,y:event.clientY,moved:false,source:!!game.state.board[Number(cell.dataset.index)]};
 try{cell.setPointerCapture(event.pointerId);}catch(e){}
});
document.addEventListener('pointermove',event=>{
 const g=boardGesture;if(!g||g.pointerId!==event.pointerId)return;
 if(g.source&&Math.hypot(event.clientX-g.x,event.clientY-g.y)>10)g.moved=true;
 if(!g.moved)return;
 g.cell.classList.add('dragging');
 if(!boardGhost){const image=g.cell.querySelector('img');if(image){boardGhost=document.createElement('div');boardGhost.className='drag-preview';const sprite=image.cloneNode();boardGhost.append(sprite);document.body.append(boardGhost);}}
 if(boardGhost){boardGhost.style.left=event.clientX-29+'px';boardGhost.style.top=event.clientY-70+'px';}
 document.querySelectorAll('.cell.drop-ready').forEach(el=>el.classList.remove('drop-ready'));
 const hit=document.elementFromPoint(event.clientX,event.clientY)?.closest('.cell');
 if(hit){const n=Number(hit.dataset.index),a=game.state.board[g.index],b=game.state.board[n];if(n!==g.index&&a&&(!b||a.c===b.c&&a.t===b.t&&(a.t!==5||b.n<10)))hit.classList.add('drop-ready');}
});
document.addEventListener('pointerup',event=>{
 const g=boardGesture;if(!g||g.pointerId!==event.pointerId)return;
 const hit=document.elementFromPoint(event.clientX,event.clientY)?.closest('.cell');
 const target=hit?Number(hit.dataset.index):null;
 clearBoardGesture();boardNativeClick={at:performance.now(),pointerId:event.pointerId};
 // Movement within the original tile is still a tap, not a failed drag.
 if(target===g.index)boardActivate(g.index);
 else if(target!==null&&g.source)boardFeedback(g.index,target);
 // Releasing outside the board cancels, with no inventory mutation.
});
document.addEventListener('pointercancel',event=>{if(boardGesture?.pointerId===event.pointerId)clearBoardGesture();});
document.addEventListener('lostpointercapture',event=>{if(boardGesture?.pointerId===event.pointerId)clearBoardGesture();});
window.addEventListener('blur',clearBoardGesture);document.addEventListener('visibilitychange',()=>{if(document.hidden)clearBoardGesture();});

document.addEventListener("click",e=>{if(Date.now()<employeeDragSuppressUntil){employeeDragSuppressUntil=0;e.preventDefault();return;}const button=e.target.closest("[data-action]");if(!button||button.disabled)return;if(button.dataset.action==="cell"&&ignoreBoardClick(e))return;const fn=actions[button.dataset.action];if(!fn)return;try{fn(button);}catch(err){toast(err.message||"这一步未能完成，请再试一次");}});
function applyTapFeedback(button){if(!button||button.disabled)return;button.classList.remove('tap-feedback');void button.offsetWidth;button.classList.add('tap-feedback');clearTimeout(button.__tapFeedbackTimer);button.__tapFeedbackTimer=setTimeout(()=>button.classList.remove('tap-feedback'),180);playClick();}
document.addEventListener('pointerdown',event=>{const target=event.target instanceof Element?event.target.closest('button,a,[role="button"]'):null;if(!target||target.disabled||event.button===2)return;if(!target.closest?.('.employee-person[data-drag-source="employee"]'))applyTapFeedback(target);if(loginStarted||$("#login-screen")?.hidden)startMusic();},{capture:true,passive:true});
document.addEventListener('keydown',event=>{if(event.repeat||!['Enter',' '].includes(event.key))return;const target=event.target instanceof Element?event.target.closest('button,a,[role="button"]'):null;if(target&&!target.disabled)applyTapFeedback(target);});
document.addEventListener("pointerup",e=>{const button=e.target.closest?.('[data-action="login-start"]');if(!button||button.disabled)return;e.preventDefault();startLogin();},{passive:false});

modal.addEventListener("click",e=>{if(e.target!==modal)return;const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();});
$("#import-file").addEventListener("change",async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>1000000)throw new Error("进度文件过大，最多1MB");const text=(await file.text()).replace(/^\uFEFF/,"");game.import(JSON.parse(text));closeModal();go("map");toast("闭环进度已恢复");}catch(err){toast("导入失败："+err.message);}e.target.value="";});
window.addEventListener("hashchange",()=>{const v=location.hash.slice(1);if(VALID_VIEWS.includes(v)&&v!==ui.view){ui.view=v;render();}});window.addEventListener("resize",()=>{if(ui.view==="customer"&&$("#sketch"))render();});window.addEventListener("storage",e=>{if(e.key!==KEY)return;storageOK=false;loadWarning="另一页修改了手游进度，本页已暂停自动保存，避免覆盖。请刷新继续，或导出当前分支。";warning();});document.addEventListener("visibilitychange",()=>{if(document.hidden){stopMusic();save();}else{game.tick();render();if(audioState.unlocked&&audioState.enabled)startMusic();}});window.addEventListener("pagehide",()=>{stopMusic();save();});
game.subscribe(kind=>{if(kind==="community-draft"){save();return;}if(kind==="tick")hud();else render();if(kind!=="tick"||Date.now()-lastWrite>2000){save();lastWrite=Date.now();}});

// Reference-element synthesis library: six categories × six tiers.
function pixelLibrary(){return `<section class="card pixel-library shine-pixel-library"><div class="pixel-section-label"><span aria-hidden="true">✦</span><h2>服装元素图鉴</h2><span aria-hidden="true">✦</span></div><p>参考图元素 · 同款10件升一阶 · 共6阶</p>${PixelWorkshop.SAMPLES.map((row,c)=>`<div class="pixel-chain"><div class="row"><b>${PixelWorkshop.categories[c]}</b><small>6阶 · ${PixelWorkshop.tierNames.join(' / ')}</small></div><div class="pixel-chain-items">${row.map((x,t)=>`<div class="pixel-chain-item"><div class="shine-tier-art">${pixelSample(c,t)}</div><small>T${t+1} · ${PixelWorkshop.tierNames[t]}</small></div>`).join('')}</div></div>`).join('')}<small class="pixel-library-note">样衣可消耗 · 成衣永久收藏</small></section>`;}
// Phone-only sheets reuse the same validated actions and rules.
Object.assign(actions,{
 orders:()=>go("customer"),
 "shop-tab":e=>{ui.shop=Number(e.dataset.id);render();},
 "shop-focus":e=>{ui.shop=Number(e.dataset.id);render();document.querySelector('.shop-panel')?.scrollIntoView({behavior:'smooth',block:'center'});},"merge-branch":e=>{ui.mergeBranch=e.dataset.branch;closeModal();render();toast(`已选择${e.dataset.branch==="dress"?"礼服面料":"外套面料"}路线`);},
 patterns:mobilePatterns,chains:()=>openModal('样衣合成图谱',pixelLibrary()),
 batch:()=>openModal('批量制作样衣',`<p class="modal-text">每次制作仍按原体力费用结算；棋盘不足或体力不足会提示。</p>${CHAINS.map((c,i)=>`<button class="settings-action" data-action="generate" data-c="${i}" data-count="5" ${game.generatorOpen(i)?'':'disabled'}>${c.name} · 连做5次<small>${c.cost*5}体力 · 生成器G${effectiveRank()+1}</small></button>`).join('')}`),
 "contest-rewards":mobileRewards,"local-ranking":mobileRanking,"mobile-help":mobileHelp,
 "set-detail":()=>openModal('套装收藏奖励',`<p class="modal-text">集齐当前套装的所有部件后，领取3,000元、25服饰券与10印章，所有店铺永久收入+5%。每套只领一次。<br>点击右侧部件查看研发与制衣来源，未拥有的预览服装不能用于评选。</p><button class="btn full" data-action="close">继续收集</button>`)
});
actions.cell=e=>boardActivate(Number(e.dataset.index));
const oldRecipe=actions.recipe;actions.recipe=e=>{closeModal();oldRecipe(e);};
const oldTake=actions['take-order'];actions['take-order']=e=>{closeModal();oldTake(e);window.scrollTo({top:0,behavior:'instant'});};
const oldReward=actions['claim-contest'];actions['claim-contest']=e=>{oldReward(e);mobileRewards();};
const oldGen=actions.generate;actions.generate=e=>{oldGen(e);if(e.dataset.count)closeModal();};
// Swipe down from the sheet header closes it. Content remains scrollable.
let sheetStart=null;modal.addEventListener('pointerdown',e=>{if(e.target.closest('.modal-top')&&!e.target.closest('button'))sheetStart={x:e.clientX,y:e.clientY};});
modal.addEventListener('pointerup',e=>{if(sheetStart&&e.clientY-sheetStart.y>65&&Math.abs(e.clientX-sheetStart.x)<60)closeModal();sheetStart=null;});modal.addEventListener('pointercancel',()=>sheetStart=null);

/* Notification view helpers. Live ticks only toggle badges, never rebuild gameplay DOM. */
function noticeState(){const mallUpgradeIds=typeof STORES==='undefined'?[]:STORES.map((_,id)=>{try{const shop=game.state.shops[id],cost=game.upgradeCost(id);return shop?.open&&cost.n>0&&game.state.coins>=cost.cost?id:null;}catch(e){return null;}}).filter(id=>id!==null);return NoticeRules.summarize(game.state,{SETS,THEMES,loopReady:game.loopSteps().every(Boolean),mallUpgradeIds});}
function noticeSlot(key,label='有可领取奖励'){return `<span class="notice-dot" data-notice-key="${esc(key)}" hidden aria-hidden="true"></span><span class="sr-only notice-copy" data-notice-copy="${esc(key)}" hidden>${esc(label)}</span>`;}
function itemIsNew(id){return game.state.owned.includes(id)&&!game.state.seenOwned.includes(id);}
function newItemTag(id){return itemIsNew(id)?`<span class="item-new-tag" data-new-item="${id}">NEW</span>`:'';}
function syncNotices(){
 const summary=noticeState();
 for(const dot of document.querySelectorAll('[data-notice-key]')){const pending=NoticeRules.eligible(dot.dataset.noticeKey,game.state,summary);dot.hidden=!pending;dot.parentElement?.classList.add('notice-host');}
 for(const copy of document.querySelectorAll('[data-notice-copy]'))copy.hidden=!NoticeRules.eligible(copy.dataset.noticeCopy,game.state,summary);
}

function profileCommentName(c){return !c?'评论':c.example?c.author:game.state.profile.nickname+' · 我';}
/* Local outfit UGC views. Example content is labeled; own works render the actual three pieces. */
function socialIcon(name){const paths={heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z',comment:'M21 11.5a8.4 8.4 0 0 1-9 8.4c-1.3 0-2.6-.3-3.7-.8L3 21l1.4-5.2A8.4 8.4 0 0 1 3 11.5a9 9 0 0 1 18 0Z',save:'M6 3h12v18l-6-4-6 4V3Z',edit:'m15 4 5 5M4 20l4-1L21 6l-4-4L4 15v5Z',send:'m3 3 18 9-18 9 4-9-4-9Zm4 9h14',close:'m6 6 12 12M6 18 18 6'};return `<svg class="social-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.heart}"/></svg>`;}
function communityAuthor(p){return `<div class="ugc-author"><span class="ugc-avatar"><img src="${model(p.own?game.state.profile.avatar:p.model)}" alt="" draggable="false"></span><span>${esc(p.own?game.state.profile.nickname+" · 我":p.author)}</span><small>${p.example?'示例':p.rewarded?'参评作品':'社区展示'}</small></div>`;}
function communityArtwork(p,detail=false){if(p.example)return `<div class="ugc-art example-art theme-${p.theme}"><img src="${model(p.model)}" alt="预制套装示例：${esc(p.title)}" draggable="false"><span class="ugc-art-label">预制套装示例</span></div>`;return `<div class="ugc-art look-collage theme-${p.theme}"><span class="collage-decoration">✧</span><div class="collage-main">${photo(p.outfit[0])}</div><div class="collage-accessory">${photo(p.outfit[2])}</div><div class="collage-shoes">${photo(p.outfit[1])}</div><span class="ugc-art-label">真实三件搭配卡</span></div>`;}
function communityActions(p){return `<div class="ugc-actions"><button class="ugc-action ${p.liked?'is-liked':''}" data-action="ugc-like" data-id="${p.id}" aria-label="${p.liked?'取消点赞':'点赞'}${esc(p.title)}" aria-pressed="${p.liked}">${socialIcon('heart')}<span>${p.likes}</span></button><button class="ugc-action" data-action="ugc-comments" data-id="${p.id}" aria-label="评论${esc(p.title)}">${socialIcon('comment')}<span>${p.comments.length}</span></button><button class="ugc-action ${p.saved?'is-saved':''}" data-action="ugc-save" data-id="${p.id}" aria-label="${p.saved?'取消收藏':'收藏'}${esc(p.title)}" aria-pressed="${p.saved}">${socialIcon('save')}<span>${p.saves}</span></button></div>`;}
function communityCard(p){const theme=THEMES.find(x=>x.id===p.theme);return `<article class="ugc-card" data-post="${p.id}"><button class="ugc-cover-button" data-action="ugc-open" data-id="${p.id}" aria-label="查看作品${esc(p.title)}">${communityArtwork(p)}<div class="ugc-card-copy"><small class="ugc-theme">#${theme.name}</small><h2>${esc(p.title)}</h2><p>${esc(p.caption||'把今天的灵感，穿成喜欢的样子。')}</p></div></button>${communityAuthor(p)}${communityActions(p)}</article>`;}
function communityComposer(){const s=game.state,theme=THEMES.find(x=>x.id===s.contest.theme),rec=s.contest.records[theme.id],score=game.score(),draft=s.community.draft,preview={own:true,example:false,theme:theme.id,outfit:rec.outfit};const hasOutfit=score.ready;return `<div class="community-back"><button class="text-btn" data-action="ugc-back">‹ 返回穿搭日记</button><small>搭配与文案会保存为草稿</small></div><header class="community-heading"><p>CREATE YOUR LOOK</p><h1>写下你的穿搭灵感</h1><span>让喜欢的衣服，拥有自己的故事。</span></header><div class="set-buttons community-theme-tabs">${THEMES.map(t=>`<button class="chip ${theme.id===t.id?'active':''}" data-action="theme" data-theme="${t.id}">${t.name}</button>`).join('')}</div><div class="composer-preview">${hasOutfit?communityArtwork(preview):`<div class="empty-collage">${icon('hanger')}<h2>选三件属于你的服装</h2><p>成衣、鞋履、配饰各一件</p></div>`}<span class="composer-score">${s.daily.contest<3?'系统预估 '+score.total+' / 300':'本次为社区展示 · 不计奖励'}</span></div><div class="contest-tools"><div><b>${theme.name}</b><small>${theme.tags.join(' / ')} · ${hasOutfit?'使用永久拥有的服装':'先完成三部位搭配'}</small></div><button class="text-btn" data-action="recommend">一键推荐 ${icon('arrow')}</button></div><div class="outfit-row">${rec.outfit.map((id,slot)=>`<button class="outfit-slot" data-action="pick-outfit" data-slot="${slot}">${id===null?`<div class="empty-art">${icon('hanger')}</div>`:photo(id)}<b>${id===null?['选择成衣','选择鞋履','选择配饰'][slot]:FASHION[id].name}</b><small>${id===null?'仅限已拥有':'点击更换'}</small></button>`).join('')}</div><section class="ugc-writing"><label for="look-title">作品标题 <small>选填 · 最多24字</small></label><input id="look-title" data-ugc-draft="title" maxlength="24" value="${esc(draft.title)}" placeholder="给这次搭配起个名字"><label for="look-caption">搭配心情 <small>选填 · 最多140字</small></label><textarea id="look-caption" data-ugc-draft="caption" maxlength="140" rows="3" placeholder="分享你的配色、风格或今天的小心情…">${esc(draft.caption)}</textarea></section>${s.crafted.length?'':`<div class="notice">完成第一件顾客制衣后，就能发布自己的作品。<button class="text-btn" data-action="orders">去经营接待顾客 →</button></div>`}<div class="ugc-publish-dock"><div><b>今日穿搭日记奖励 ${s.daily.contest}/3</b><small>额外投稿仅社区展示，不发资源、不更新成绩。</small></div><button class="btn" data-action="enter-contest" ${!score.ready||!s.crafted.length?'disabled':''}>${s.daily.contest<3?'发布并参评':'发布到社区'} ${socialIcon('send')}</button></div><p class="ugc-local-note">本地UGC试玩 · 三件搭配卡不是分层人物换装；点赞与收藏不改变穿搭日记分数。</p>`;}
function renderContest(){if(ui.communityPage==='compose')return communityComposer();const s=game.state,posts=game.communityFeed({filter:ui.communityFilter,theme:ui.communityTheme});return `<header class="community-heading"><p>FASHION & LITTLE STORIES</p><div class="community-title-row"><h1>穿搭日记</h1><button class="community-reward-button" data-action="contest-rewards">${icon('cup')}穿搭日记奖励${noticeSlot('nav:contest')}</button></div><span>每一份搭配，都值得被看见。</span></header><section class="community-invitation"><div><small>今日主题 · 穿搭日记</small><h2>把灵感，穿成自己的故事</h2><p>分享搭配，留下评论，收藏心动的作品。</p></div><button class="btn" data-action="ugc-compose">${socialIcon('edit')}${s.community.draft.title||s.community.draft.caption?'继续创作':'发布搭配'}</button><span class="invitation-flower">✿</span></section><div class="community-tabs">${[['discover','发现作品'],['mine','我的作品'],['saved','收藏夹']].map(([key,label])=>`<button data-action="ugc-filter" data-filter="${key}" class="${ui.communityFilter===key?'active':''}" ${ui.communityFilter===key?'aria-current="page"':''}>${label}${key==='mine'?`<small>${s.community.posts.length}</small>`:key==='saved'?`<small>${s.community.saved.length}</small>`:''}</button>`).join('')}</div><div class="community-filter-row">${[['all','全部主题'],...THEMES.map(t=>[t.id,t.name])].map(([key,name])=>`<button class="chip ${ui.communityTheme===key?'active':''}" data-action="ugc-feed-theme" data-theme="${key}">${name}${noticeSlot(key==='all'?'nav:contest':'theme:'+key)}</button>`).join('')}</div><p class="ugc-simulation-note"><span>本地UGC试玩</span> 示例作品与互动数为模拟数据，尚未接入真实玩家社区。</p>${posts.length?`<div class="ugc-feed">${posts.map(communityCard).join('')}</div>`:`<section class="ugc-empty">${socialIcon(ui.communityFilter==='saved'?'save':'edit')}<h2>${ui.communityFilter==='saved'?'收藏，让灵感有个家':'这里等待你的第一份搭配'}</h2><p>${ui.communityFilter==='saved'?'点击作品下的收藏按钮，下次从这里找回喜欢。':'选择已拥有的服装，分享一份自己的穿搭日记。'}</p><button class="btn" data-action="${ui.communityFilter==='saved'?'ugc-discover':'ugc-compose'}">${ui.communityFilter==='saved'?'去发现作品':'创作第一份搭配'}</button></section>`}<p class="ugc-local-note">作品收藏与服装衣橱分开；收藏帖子不会直接获得其中的服装。</p>`;}
function openCommunityPost(id,focusComment=false){const p=game.communityPost(id),theme=THEMES.find(t=>t.id===p.theme);ui.detailPost=id;const draft=ui.commentDrafts[id]||'',replyId=ui.replyTo[id]||null,parent=p.comments.find(x=>x.id===replyId);openModal('作品详情',`<div class="ugc-detail" data-detail-post="${id}">${communityAuthor(p)}${communityArtwork(p,true)}<div class="ugc-detail-copy"><small class="ugc-theme">#${theme.name}</small><h2>${esc(p.title)}</h2><p>${esc(p.caption||'把今天的灵感，穿成喜欢的样子。')}</p><span class="ugc-post-kind">${p.example?'模拟搭配师的预制套装示例':p.rewarded?'穿搭日记评分 '+p.score+'分 · 参与奖励已结算':'你的社区展示作品 · 不计分、不发资源'}</span></div>${communityActions(p)}<div class="ugc-used-pieces">${p.outfit.map(id=>`<button data-action="item" data-id="${id}" aria-label="查看${FASHION[id].name}">${photo(id)}<small>${FASHION[id].name}</small></button>`).join('')}</div><p class="ugc-local-note">点击单品查看来源；收藏帖子不等于拥有服装。</p><div class="ugc-comment-heading"><h3>评论 <small>${p.comments.length}</small></h3>${p.own?`<button class="text-btn" data-action="ugc-delete-post-request" data-id="${id}">删除作品</button>`:''}</div><div class="ugc-comment-list">${p.comments.length?p.comments.map(c=>`<article class="ugc-comment" data-comment="${c.id}"><div><b>${esc(c.example?c.author:game.state.profile.nickname+" · 我")}</b><small>${c.example?'示例评论':'你的本地评论'}</small></div>${c.parentId?`<span class="ugc-reply-context">回复 ${esc(profileCommentName(p.comments.find(x=>x.id===c.parentId)))}</span>`:''}<p>${esc(c.text)}</p><div class="ugc-comment-tools"><button data-action="ugc-reply" data-id="${id}" data-comment="${c.id}">回复</button>${c.example?'':`<button data-action="ugc-delete-comment" data-id="${id}" data-comment="${c.id}">删除</button>`}</div></article>`).join(''):`<div class="ugc-comments-empty">写下第一句温柔的搭配建议吧。</div>`}</div><div class="ugc-comment-composer">${parent?`<div class="ugc-reply-banner">回复 ${esc(parent.example?parent.author:game.state.profile.nickname+' · 我')}<button data-action="ugc-cancel-reply" data-id="${id}" aria-label="取消回复">${socialIcon('close')}</button></div>`:''}<label class="sr-only" for="ugc-comment-input">写下评论</label><textarea id="ugc-comment-input" data-comment-draft="${id}" maxlength="160" rows="2" placeholder="分享你的搭配想法（最多160字）">${esc(draft)}</textarea><button id="ugc-comment-send" class="btn" data-action="ugc-comment-send" data-id="${id}" ${!draft.trim()?'disabled':''}>发送 ${socialIcon('send')}</button></div><p class="ugc-local-note">互动仅保存在本地；不会向其他玩家发送，也不会生成假回复。</p></div>`);if(focusComment){modal.querySelector('.ugc-comment-heading')?.scrollIntoView({block:'start',behavior:'instant'});$('#ugc-comment-input')?.focus({preventScroll:true});}}
function refreshCommunityDetail(id){if(modal.open&&modal.querySelector('[data-detail-post]')?.dataset.detailPost===id)openCommunityPost(id);}
function openCommunityRewards(){mobileRewards();modal.querySelector('.modal-top')?.insertAdjacentHTML('afterend',`<div class="set-buttons reward-theme-tabs">${THEMES.map(t=>`<button class="chip ${game.state.contest.theme===t.id?'active':''}" data-action="ugc-reward-theme" data-theme="${t.id}">${t.name}${noticeSlot('theme:'+t.id)}</button>`).join('')}</div>`);syncNotices();}
function publishCommunityLook(){if(ui.publishBusy)return;ui.publishBusy=true;try{const result=game.publishLook(ui.ugcRequestId||game.state.community.draft.id);ui.communityPage='feed';ui.communityFilter='mine';ui.communityTheme='all';render();const p=game.communityPost(result.post.id);openModal(result.duplicate?'这份作品已经发布':'你的搭配，已被记录',`<div class="publication-result">${communityArtwork(p)}<h2>${esc(p.title)}</h2><p>${result.duplicate?'不会重复结算奖励。':p.rewarded?'穿搭日记评分 '+p.score+'分 · 600元 / 8券 / 5印章已入账，体力恢复至多10点（按上限结算）。':'本次只发布社区展示作品，不计分、不发资源。'}</p><div class="modal-actions"><button class="btn" data-action="ugc-open" data-id="${p.id}">查看作品与评论</button><button class="btn light" data-action="contest-rewards">查看穿搭日记奖励${noticeSlot('nav:contest')}</button></div></div>`);}finally{ui.publishBusy=false;}}
Object.assign(ui,{communityPage:'feed',communityFilter:'discover',communityTheme:'all',detailPost:null,ugcRequestId:null,publishBusy:false,commentDrafts:{},replyTo:{}});
Object.assign(actions,{
 'ugc-compose':()=>{ui.communityPage='compose';ui.ugcRequestId=game.state.community.draft.id;closeModal();render();window.scrollTo({top:0,behavior:'instant'});},
 'ugc-back':()=>{ui.communityPage='feed';render();window.scrollTo({top:0,behavior:'instant'});},
 'ugc-filter':e=>{ui.communityFilter=e.dataset.filter;render();},'ugc-discover':()=>{ui.communityFilter='discover';ui.communityTheme='all';render();},
 'ugc-feed-theme':e=>{ui.communityTheme=e.dataset.theme;render();},
 'ugc-open':e=>openCommunityPost(e.dataset.id),'ugc-comments':e=>openCommunityPost(e.dataset.id,true),
 'ugc-like':e=>{game.likeLook(e.dataset.id);refreshCommunityDetail(e.dataset.id);},'ugc-save':e=>{game.saveLook(e.dataset.id);refreshCommunityDetail(e.dataset.id);},
 'ugc-comment-send':e=>{const id=e.dataset.id;const posted=game.commentLook(id,ui.commentDrafts[id]||'',ui.replyTo[id]||null);ui.commentDrafts[id]='';ui.replyTo[id]=null;openCommunityPost(id);modal.querySelector(`[data-comment="${posted.id}"]`)?.scrollIntoView({block:'nearest',behavior:'instant'});toast('评论已保存在本地');},
 'ugc-reply':e=>{ui.replyTo[e.dataset.id]=e.dataset.comment;openCommunityPost(e.dataset.id,true);},'ugc-cancel-reply':e=>{ui.replyTo[e.dataset.id]=null;openCommunityPost(e.dataset.id);},
 'ugc-delete-comment':e=>{game.deleteLookComment(e.dataset.comment);ui.replyTo[e.dataset.id]=null;openCommunityPost(e.dataset.id);},
 'ugc-delete-post-request':e=>openModal('删除这份作品？',`<p class="modal-text">作品和本地互动记录会移除。已结算的奖励与每日参评次数不会返还，也不会因此重新获得奖励。</p><div class="modal-actions"><button class="btn light" data-action="close">保留作品</button><button class="btn" data-action="ugc-delete-post" data-id="${esc(e.dataset.id)}">确认删除</button></div>`),
 'ugc-delete-post':e=>{game.deleteLook(e.dataset.id);closeModal();render();toast('作品已删除，服装仍永久保留');},
 'ugc-reward-theme':e=>{game.selectTheme(e.dataset.theme);openCommunityRewards();},'contest-rewards':openCommunityRewards,'enter-contest':publishCommunityLook
});
delete actions.practice;const communityClaim=actions['claim-contest'];actions['claim-contest']=e=>{communityClaim(e);openCommunityRewards();};
document.addEventListener('input',e=>{try{if(e.target.matches('[data-ugc-draft]'))game.communityDraft({[e.target.dataset.ugcDraft]:e.target.value});if(e.target.matches('[data-comment-draft]')){ui.commentDrafts[e.target.dataset.commentDraft]=e.target.value;$('#ugc-comment-send').disabled=!e.target.value.trim();}}catch(err){toast(err.message);}});

/* Personal space: local identity, real progression and owned-set display. */
function profileIcon(name){const paths={hanger:'m8 5 4-2 3 2v3l-3 2M12 10 2 18v2h20v-2L12 10',palette:'M12 3a9 9 0 1 0 0 18h2a3 3 0 0 0 0-6h-1a2 2 0 0 1 0-4h2a6 6 0 0 0-3-8ZM6 10h.01M9 6h.01M15 6h.01M5 15h.01',rank:'M4 4h16v16H4V4Zm4 4h8M8 12h8M8 16h5',medal:'m7 3 5 8 5-8H7Zm5 6a6 6 0 1 0 0 12 6 6 0 0 0 0-12Zm0 3 1 2 2 .3-1.5 1.5.4 2.2-1.9-1-1.9 1 .4-2.2L9 14.3l2-.3 1-2Z',share:'M8 7H3v14h14v-5M12 3h9v9M21 3 10 14',gift:'M3 10h18v4H3v-4Zm2 4v7h14v-7M12 10v11M12 10C6 10 5 8 6 5c2-2 5 0 6 5Zm0 0c6 0 7-2 6-5-2-2-5 0-6 5Z',edit:'m15 4 5 5M4 20l4-1L21 6l-4-4L4 15v5Z',copy:'M8 8h12v13H8V8ZM16 8V3H3v13h5',back:'m14 5-7 7 7 7M7 12h14',help:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20Zm-3-14a3 3 0 0 1 6 0c0 3-3 2-3 5M12 17h.01',settings:'M4 6h16M4 12h16M4 18h16M8 3v6M16 9v6M10 15v6',calendar:'M4 5h16v16H4V5ZM8 2v6M16 2v6M4 10h16M8 14h2M14 14h2M8 17h2'};return `<svg class="profile-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.help}"/></svg>`;}
function profileSet(){return SETS.find(x=>x.id===game.state.profile.displaySet);}const PROFILE_DRESS_LOOKS=[{id:1,name:'粉毛披肩造型',sub:'轻盈流光',src:'model-3.webp',tag:'优雅',parts:{hair:'dress-look-2-hair-clean.png',coat:'dress-look-2-coat-clean.png',accessory:'dress-look-2-necklace-clean.png',dress:'dress-look-2-bottom-clean.png',shoes:'dress-look-2-shoes-clean.png'},layers:['dress-look-2-bottom-clean.png','dress-look-2-coat-clean.png','dress-look-2-necklace-clean.png','dress-look-2-hair-clean.png','dress-look-2-shoes-clean.png']},{id:2,name:'金色层叠造型',sub:'日光层叠',src:'dress-look-1.png',tag:'华丽',parts:{hair:'dress-look-1-hair-clean.png',top:'dress-look-1-top-clean.png',dress:'dress-look-1-bottom-clean.png',shoes:'dress-look-1-shoes-clean.png'},layers:['dress-look-1-bottom-clean.png','dress-look-1-top-clean.png','dress-look-1-hair-clean.png','dress-look-1-shoes-clean.png']},{id:3,name:'西装造型',sub:'都会锋芒',src:'dress-look-2.png',tag:'干练',parts:{hair:'dress-look-3-hair-clean.png',coat:'dress-look-3-coat-clean.png',pants:'dress-look-3-bottom-clean.png',accessory:'dress-look-3-necklace-clean.png'},layers:['dress-look-3-bottom-clean.png','dress-look-3-coat-clean.png','dress-look-3-necklace-clean.png','dress-look-3-hair-clean.png']},{id:4,name:'银裙造型',sub:'银色派对',src:'dress-look-3.png',tag:'闪耀',parts:{hair:'dress-look-4-hair-clean.png',coat:'dress-look-4-coat-clean.png',dress:'dress-look-4-bottom-clean.png',accessory:'dress-look-4-necklace-clean.png',shoes:'dress-look-4-shoes-clean.png'},layers:['dress-look-4-bottom-clean.png','dress-look-4-coat-clean.png','dress-look-4-necklace-clean.png','dress-look-4-hair-clean.png','dress-look-4-shoes-clean.png']}];
function profileDressLook(id){if(Number(id)===0)return {id:0,name:'基础角色',sub:'未换装',src:'dress-base-character.png',tag:'基础',parts:{},layers:[]};return PROFILE_DRESS_LOOKS.find(x=>x.id===Number(id))||PROFILE_DRESS_LOOKS[0];}
const DRESS_CATEGORY_META=[['hair','发型','◒'],['top','上装','👚'],['bottom','下装','👗'],['shoes','鞋履','👠'],['accessory','饰品','💎'],['socks','袜子','🧦'],['cat','大喵','🐱'],['set','套装','🎀'],['nail','美甲','💅'],['makeup','妆容','💄'],['skin','肤色','◉'],['scene','场景','▧'],['environment','环境','✦'],['camera','入境','◐']];
const DRESS_PART_OPTIONS={
 hair:[{name:'基础发型',src:''},{name:'披肩长发',src:'dress-look-2-hair-clean.png',look:1},{name:'金色高束发',src:'dress-look-1-hair-clean.png',look:2},{name:'西装短发',src:'dress-look-3-hair-clean.png',look:3},{name:'银色长发',src:'dress-look-4-hair-clean.png',look:4}],
 top:[{name:'基础上衣',src:''},{name:'粉色披肩',src:'dress-look-2-coat-clean.png',look:1},{name:'金色层叠上衣',src:'dress-look-1-top-clean.png',look:2},{name:'西装外套',src:'dress-look-3-coat-clean.png',look:3},{name:'银裙外套',src:'dress-look-4-coat-clean.png',look:4}],
 bottom:[{name:'基础下装',src:''},{name:'粉色礼服裙',src:'dress-look-2-bottom-clean.png',look:1},{name:'金色层叠裙',src:'dress-look-1-bottom-clean.png',look:2},{name:'西装长裤',src:'dress-look-3-bottom-clean.png',look:3},{name:'银色礼裙',src:'dress-look-4-bottom-clean.png',look:4}],
 shoes:[{name:'基础鞋履',src:''},{name:'粉色高跟鞋',src:'dress-look-2-shoes-clean.png',look:1},{name:'金色高跟鞋',src:'dress-look-1-shoes-clean.png',look:2},{name:'银色高跟鞋',src:'dress-look-4-shoes-clean.png',look:4}],
 accessory:[{name:'暂无饰品',src:''},{name:'粉色项链',src:'dress-look-2-necklace-clean.png',look:1},{name:'西装项链',src:'dress-look-3-necklace-clean.png',look:3},{name:'银色项链',src:'dress-look-4-necklace-clean.png',look:4}]
};
function dressPresetParts(id){const look=profileDressLook(id);return {hair:look.parts.hair||'',top:look.parts.coat||look.parts.top||'',bottom:look.parts.dress||look.parts.pants||look.parts.bottom||'',shoes:look.parts.shoes||'',accessory:look.parts.accessory||''};}
function profileDressSelections(){const fallback=dressPresetParts(game.state.profile.dressLook||1),saved=game.state.profile.dressParts||{};return {...fallback,...Object.fromEntries(Object.entries(saved).filter(([slot,src])=>DRESS_PART_OPTIONS[slot]&&typeof src==='string'))};}
function dressPresetForSelection(selection){return PROFILE_DRESS_LOOKS.find(look=>Object.entries(dressPresetParts(look.id)).every(([slot,src])=>(selection[slot]||'')===src))?.id||null;}
/*
 * The supplied part PNGs are item cut-outs rather than a shared character
 * canvas.  Overlaying them on the base body produces doubled faces, skin and
 * legs.  Until the art team exports true canvas-aligned layers, the playable
 * preview uses the validated full-look composite for the selected outfit.
 * The slot state and item selection remain independent, so the interaction
 * still follows the dressing flow and can be swapped to real layers later
 * without changing save data.
 */
function profileDressLayerMarkup(look,extra='',selection=profileDressSelections()){
 const src=look?.src||'dress-base-character.png';
 const selected=Object.entries(selection||{}).filter(([,value])=>value).map(([slot,value])=>`${slot}:${value}`).join('|');
 return `<div class="profile-layer-stack ${extra} stable-composite-preview" data-preview-look="${Number(look?.id)||1}" data-selected-parts="${esc(selected)}"><img class="profile-layer composite profile-dress-composite" data-dress-source="${esc(src)}" src="${asset(src)}" alt="${esc(look?.name||'当前造型')}" draggable="false"></div>`;
}
function profileDisplayModel(p,set){const look=profileDressLook(p.dressLook);return asset(look.src||'dress-base-character.png');}

function profileRank(){return game.state.level>=10?'明星设计师':game.state.level>=4?'新锐设计师':'见习设计师';}
function profileNextIncome(){const s=game.state,id=s.shops.findIndex(x=>x.open&&x.level<50);if(id<0)return game.income();const shop=s.shops[id],factor=1+shop.business.length*.2+game.employeeBonus(id)+s.setClaims.length*.05+game.businessBonus(id);return game.income()+STORES[id].step*factor;}
function profileShortcut(action,label,symbol,extra=''){return `<button class="profile-shortcut" data-action="${action}" aria-label="${label}"><span class="profile-shortcut-icon">${profileIcon(symbol)}${extra}</span><span>${label}</span></button>`;}
function profileRoom(){return `<img class="profile-room-art" src="${asset('profile-dressing-room-v1.webp')}" alt="" draggable="false">`;}
function renderProfile(){const s=game.state,p=s.profile,set=profileSet(),need=LoopGame.xpNeed(s.level),nextIncome=profileNextIncome();return `<section class="profile-page decor-${p.decor}" aria-label="个人信息"><div class="profile-room">${profileRoom()}</div><header class="profile-top"><div><h1>个人信息</h1><button data-action="profile-help" class="profile-help" aria-label="个人信息说明">${profileIcon('help')}</button></div><button class="profile-settings" data-action="settings" aria-label="试玩与存档设置">${profileIcon('settings')}<span>设置</span></button></header><div class="profile-stage"><div class="profile-light"></div>${profileDressLayerMarkup(profileDressLook(p.dressLook),"profile-model",profileDressSelections())}<div class="profile-side profile-side-left">${profileShortcut('profile-dress','换装','hanger')}${profileShortcut('profile-decor','装饰','palette')}${profileShortcut('profile-bonus','等级加成','rank')}${profileShortcut('profile-honors','个人荣誉','medal')}</div><div class="profile-side profile-side-right">${profileShortcut('profile-invite','邀请试玩','share')}${profileShortcut('profile-daily','每日补给','gift',noticeSlot('daily'))}</div><span class="profile-display-note">${set.id==='sunny'?'默认预制形象 · 不代表拥有整套服装':'已集齐套装 · 预制形象展示'}</span></div><article class="profile-card"><div class="profile-card-top"><button class="profile-avatar" data-action="profile-avatar" aria-label="修改个人头像"><span class="profile-avatar-art"><img src="${model(p.avatar)}" alt="${esc(p.nickname)}的头像" draggable="false"></span><span>${profileIcon('edit')}</span></button><div class="profile-basics"><button class="profile-nickname" data-action="profile-edit" aria-label="修改昵称与生日"><b>${esc(p.nickname)}</b>${profileIcon('edit')}</button><div class="profile-id-row"><span>本地ID：<b>${p.id}</b></span><button class="profile-copy" data-action="profile-copy" aria-label="复制玩家ID">${profileIcon('copy')}</button></div><button class="profile-birthday" data-action="profile-edit" aria-label="修改生日"><span>生日：${p.birthday?p.birthday.replace('-','月')+'日':'未设置'}</span>${profileIcon('calendar')}</button></div><div class="profile-region"><span class="profile-card-sparkle">✦ ✧ ✦</span><button data-action="profile-club">名媛会：暂无</button><span>区服：本地试玩区</span></div></div><div class="profile-rank-line"><span class="profile-rank">${s.level}级 · ${profileRank()}</span><span class="profile-collection">收藏 ${s.owned.length}/${FASHION.length}</span></div><div class="profile-progress-panel"><div class="profile-progresses"><div class="profile-progress-row"><span>阅历</span><div class="profile-meter experience" role="progressbar" aria-label="玩家阅历" aria-valuemin="0" aria-valuemax="${need}" aria-valuenow="${s.xp}"><i style="width:${Math.min(100,s.xp/need*100)}%"></i><b>${s.level===30?'已达试玩等级上限':s.xp+' / '+need}</b></div></div><div class="profile-progress-row"><span>收入</span><div class="profile-meter revenue" role="progressbar" aria-label="下一次店铺升级的秒收入目标" aria-valuemin="0" aria-valuemax="${nextIncome}" aria-valuenow="${game.income()}"><i style="width:${Math.min(100,game.income()/nextIncome*100)}%"></i><b>${fmt(game.income())} / ${fmt(nextIncome)} 元/秒</b></div></div><small>收入目标：下一次店铺升级</small></div><button class="profile-upgrade" data-action="profile-level">升级${profileIcon('rank')}</button></div></article><footer class="profile-footer"><button class="profile-back" data-action="profile-back" aria-label="返回上一页">${profileIcon('back')}</button><span>把喜欢的自己，留在这里。</span><small>本地个人空间</small></footer></section>`;}
function syncProfileHUD(){const p=game.state.profile;const current=$('.avatar img');if(current&&current.dataset.avatar!==String(p.avatar)){$('.avatar').innerHTML=`<img src="${model(p.avatar)}" data-avatar="${p.avatar}" alt="${esc(p.nickname)}的头像" draggable="false">`;}const label=$('.player-copy>b');if(label)label.textContent=p.nickname+'的设计事务所';$('.player')?.setAttribute('aria-label','打开'+p.nickname+'的个人信息');const level=$('#character-level');if(level)level.textContent='LV '+game.state.level;const rank=$('#designer-rank');if(rank){rank.textContent=profileRank();rank.title=profileRank();}$('.player')?.setAttribute('aria-label','打开'+game.state.profile.nickname+'的个人信息，角色LV '+game.state.level+'，'+profileRank());}
function profileEdit(){const p=game.state.profile;openModal('编辑个人资料',`<form id="profile-edit-form" class="profile-form"><label for="profile-nickname-input">昵称 <small>1～12个字</small></label><input id="profile-nickname-input" name="nickname" maxlength="24" value="${esc(p.nickname)}" autocomplete="nickname" required><label>生日 <small>仅保存月日，可不填写</small></label><div class="profile-date-fields"><label class="sr-only" for="profile-month">月份</label><select id="profile-month" aria-label="生日月份"><option value="">未设置</option>${Array.from({length:12},(_,i)=>`<option value="${i+1}" ${Number(p.birthday.slice(0,2))===i+1?'selected':''}>${i+1}月</option>`).join('')}</select><label class="sr-only" for="profile-day">日期</label><select id="profile-day" aria-label="生日日期"><option value="">未设置</option>${Array.from({length:31},(_,i)=>`<option value="${i+1}" ${Number(p.birthday.slice(3))===i+1?'selected':''}>${i+1}日</option>`).join('')}</select></div><p class="profile-form-error" id="profile-edit-error" role="alert"></p><p class="modal-text">个人资料只保存在当前浏览器，不发送到服务器；更换设备时可通过设置导出进度。</p><div class="modal-actions"><button type="button" class="btn light" data-action="close">取消</button><button type="submit" class="btn">保存资料</button></div></form>`);}
function profileAvatars(){openModal('选择个人头像',`<p class="modal-text">头像为免费个人装饰，不会获得图中服装，也不改变评选搭配。</p><div class="profile-avatar-grid">${SETS.map(set=>`<button class="profile-avatar-choice ${game.state.profile.avatar===set.model?'selected':''}" data-action="profile-avatar-select" data-model="${set.model}" aria-label="使用${set.name}头像" aria-pressed="${game.state.profile.avatar===set.model}"><span><img src="${model(set.model)}" alt="" draggable="false"></span><b>${set.name}</b>${game.state.profile.avatar===set.model?'<small>使用中</small>':'<small>选择头像</small>'}</button>`).join('')}</div>`);}
const PROFILE_PART_SLOTS=[
 {slot:'hair',label:'发型',ids:[1,6,11,17,20]},
 {slot:'accessory',label:'饰品',ids:[2,7,12,18,22,23]},
 {slot:'top',label:'上装',ids:[3,8,13,21]},
 {slot:'bottom',label:'下装',ids:[4,9,14]},
 {slot:'shoes',label:'鞋履',ids:[5,15,19,24]}
];
function profilePartSelections(){return {...(FashionProfile.DEFAULT_PARTS||{hair:1,accessory:2,top:3,bottom:4,shoes:5}),...(game.state.profile.parts||{})};}
function profilePartsEditor(){const selected=profilePartSelections(),owned=game.state.owned;return `<section class="profile-parts-editor"><div class="profile-parts-heading"><div><b>首套换装 · 分部件搭配</b><small>发型、饰品、上装、下装和鞋履可独立替换</small></div><span>5部件</span></div><div class="profile-parts-grid">${PROFILE_PART_SLOTS.map(slot=>{const active=selected[slot.slot],item=FASHION[active];return `<article class="profile-part-slot"><header><b>${slot.label}</b><small>${item?.name||'未选择'}</small></header><div class="profile-part-options">${slot.ids.map(id=>{const x=FASHION[id],isActive=id===active,canUse=owned.includes(id)||isActive;return `<button class="profile-part-option ${isActive?'selected':''} ${canUse?'':'locked'}" data-action="profile-part-select" data-part-slot="${slot.slot}" data-part-id="${id}" ${canUse?'':'disabled'} aria-label="${slot.label}：${x.name}${isActive?'，已装备':''}"><img src="${art(id)}" alt="${x.name}" draggable="false"><span>${x.name}</span>${isActive?'<em>已装备</em>':canUse?'<small>换上</small>':'<small>未拥有</small>'}</button>`;}).join('')}</div></article>`;}).join('')}</div><p class="profile-parts-note">基础信息与第一套「元气午后」使用新的粉色礼服贴图；部件资源会同步出现在衣橱中。</p></section>`;}
function profileDress(){const current=profileDressLook(game.state.profile.dressLook),owned=game.state.owned;const displayParts=current.id===0?PROFILE_DRESS_LOOKS[0].parts:current.parts;const slotLabels={hair:'hair',coat:'top',top:'top',dress:'bottom',pants:'bottom',accessory:'accessory',shoes:'shoes'};const partEntries=Object.entries(displayParts);const partCards=partEntries.map(([slot,src])=>{const category=slotLabels[slot]||slot;const label=({hair:'发型',coat:'上衣',top:'上衣',dress:'下装',pants:'下装',accessory:'饰品',shoes:'鞋子'}[slot]||slot);return `<button class="dress-shine-part profile-reference-part" data-action="profile-dress-part" data-dress-category="${category}" data-part-slot="${slot}" data-part-src="${src}" aria-label="查看${label}部件"><span><img src="${asset(src)}" alt="${label}部件" draggable="false"></span><b>${label}</b><small>已装备</small></button>`;}).join('');const categories=[['top','上衣','👚'],['bottom','下装','👗'],['socks','袜子','🧦'],['shoes','鞋子','👠'],['accessory','饰品','💎'],['cat','大喵','🐱'],['set','套装','🎀'],['nail','美甲','💅'],['makeup','妆容','💄'],['skin','肤色','◉'],['scene','场景','▧'],['environment','环境','✦'],['camera','入境','◐']];const categoryButtons=categories.map(([id,label,mark],i)=>`<button class="dress-shine-category ${i===0?'active':''}" data-action="profile-dress-category" data-category="${id}" aria-label="${label}"><span>${mark}</span><b>${label}</b>${id==='environment'?'<i>NEW</i>':''}</button>`).join('');openModal('个人形象 · 换装',`<section class="profile-dress-reference dress-shine-reference" data-dress-look="${current.id}" style="--shine-room:url('${asset('profile-dressing-room-v1.webp')}')"><header class="dress-shine-top"><button class="dress-shine-back" data-action="close" aria-label="返回个人信息">‹</button><div class="dress-shine-score"><span>✦</span><b>${current.id||1}</b><em>/ 4</em><strong>›</strong></div><div class="dress-shine-top-actions"><button data-action="profile-dress-tool" data-tool="camera" aria-label="拍照">◉</button><button data-action="profile-dress-tool" data-tool="favorite" aria-label="收藏">★</button></div><button class="profile-reference-close dress-shine-close" data-action="close" aria-label="关闭换装">×</button></header><div class="dress-shine-title"><small>STYLE COLLECTION</small><b>${current.name}</b><span>${current.sub}</span></div><aside class="dress-shine-left"><button data-action="profile-dress-catalog"><span>▣</span><b>相册</b></button><button data-action="profile-dress-attrs"><span>◇</span><b>3D影棚</b></button><button data-action="profile-dress-tool" data-tool="new"><span>＋</span><b>上新</b><i>NEW</i></button><button data-action="profile-dress-tool" data-tool="settings"><span>⚙</span></button><button data-action="profile-dress-tool" data-tool="undo"><span>↶</span></button><button data-action="profile-dress-tool" data-tool="redo"><span>↷</span></button><button data-action="profile-dress-tool" data-tool="delete"><span>⌫</span></button><button data-action="profile-dress-tool" data-tool="search"><span>⌕</span></button><button data-action="profile-dress-tool" data-tool="like"><span>♡</span></button></aside><main class="dress-shine-stage"><div class="dress-shine-halo"></div><div class="dress-shine-stars">✦　·　✧　·　✦</div>${profileDressLayerMarkup(current,'profile-dress-preview dress-shine-preview')}<button class="profile-dress-arrow prev dress-shine-arrow" data-action="profile-dress-prev" aria-label="上一套服装">‹</button><button class="profile-dress-arrow next dress-shine-arrow" data-action="profile-dress-next" aria-label="下一套服装">›</button><span class="dress-shine-caption">${current.sub} · 点击右侧分类查看部件</span></main><aside class="dress-shine-right"><div class="dress-shine-category-list">${categoryButtons}</div><div class="dress-shine-parts"><h3>当前搭配 <small>${partEntries.length}件</small></h3>${partCards||'<p>基础形象</p>'}</div></aside><footer class="dress-shine-bottom"><button class="dress-shine-save" data-action="profile-dress-confirm">▣ 保存搭配</button><button class="dress-shine-round" data-action="profile-dress-tool" data-tool="outfit" aria-label="搭配分享">◈</button><button class="dress-shine-round" data-action="profile-dress-tool" data-tool="dress" aria-label="查看穿搭">♧</button></footer></section>`);}
function dressPartPicker(category,selection){const options=DRESS_PART_OPTIONS[category]||[];return options.map((option,index)=>{const src=option.src||'',selected=(selection[category]||'')===src,thumb=src?`<img src="${asset(src)}" alt="${option.name}" draggable="false">`:`<span class="dress-shine-empty-part">基础</span>`;return `<button class="dress-shine-part ${selected?'selected':''}" data-action="profile-dress-part" data-dress-category="${category}" data-part-src="${esc(src)}" aria-pressed="${selected}" aria-label="${option.name}${selected?'，已装备':'，点击换上'}"><span>${thumb}</span><b>${option.name}</b><small>${selected?'已装备':'点击换上'}</small></button>`;}).join('');}
function applyDressSelection(selection,message,remember=true,previewLook){const current=profileDressSelections();if(remember){ui.dressUndo=[...ui.dressUndo.slice(-11),{selection:current,look:game.state.profile.dressLook}];ui.dressRedo=[];}const preset=dressPresetForSelection(selection);const nextLook=Number(previewLook||preset||game.state.profile.dressLook||1);game.updateProfile({dressParts:selection,dressLook:nextLook});profileDressV2();if(message)toast(message);}
function profileDressV2(){const selection=profileDressSelections(),preset=dressPresetForSelection(selection),current=profileDressLook(preset||game.state.profile.dressLook||1),category=DRESS_PART_OPTIONS[ui.dressCategory]?ui.dressCategory:'top',categoryMeta=DRESS_CATEGORY_META.find(x=>x[0]===category)||DRESS_CATEGORY_META[1],title=preset?current.name:'自选搭配',subtitle=preset?current.sub:'已混搭 · 点击右侧分类替换部件',categoryButtons=DRESS_CATEGORY_META.map(([id,label,mark],index)=>`<button class="dress-shine-category ${category===id?'active':''} ${DRESS_PART_OPTIONS[id]?'':'is-locked'}" data-action="profile-dress-category" data-category="${id}" aria-label="${label}"><span>${mark}</span><b>${label}</b>${id==='environment'?'<i>NEW</i>':''}</button>`).join('');openModal('个人形象 · 换装',`<section class="profile-dress-reference dress-shine-reference" data-dress-look="${preset||0}" style="--shine-room:url('${asset('profile-dressing-room-v1.webp')}')"><header class="dress-shine-top"><button class="dress-shine-back" data-action="close" aria-label="返回个人信息">‹</button><div class="dress-shine-score"><span>✦</span><b>${preset||'自选'}</b><em>/ 4</em><strong>›</strong></div><div class="dress-shine-top-actions"><button data-action="profile-dress-tool" data-tool="camera" aria-label="拍照">◉</button><button data-action="profile-dress-tool" data-tool="favorite" aria-label="收藏">★</button></div><button class="profile-reference-close dress-shine-close" data-action="close" aria-label="关闭换装">×</button></header><div class="dress-shine-title"><small>STYLE COLLECTION</small><b>${title}</b><span>${subtitle}</span></div><div class="dress-shine-preset"><button data-action="profile-dress-preset" aria-label="切换预设搭配"><span>⌄</span><b>${preset?'自选搭配 '+preset:'自选搭配'}</b><small>点击切换预设</small></button><button data-action="profile-dress-reset" aria-label="恢复当前预设">↺</button></div><aside class="dress-shine-left"><button data-action="profile-dress-catalog"><span>▣</span><b>相册</b></button><button data-action="profile-dress-attrs"><span>◇</span><b>3D影棚</b></button><button data-action="profile-dress-tool" data-tool="new"><span>＋</span><b>上新</b><i>NEW</i></button><button data-action="profile-dress-tool" data-tool="settings"><span>⚙</span></button><button data-action="profile-dress-tool" data-tool="undo"><span>↶</span></button><button data-action="profile-dress-tool" data-tool="redo"><span>↷</span></button><button data-action="profile-dress-tool" data-tool="delete"><span>⌫</span></button><button data-action="profile-dress-tool" data-tool="search"><span>⌕</span></button><button data-action="profile-dress-tool" data-tool="like"><span>♡</span></button></aside><main class="dress-shine-stage"><div class="dress-shine-halo"></div><div class="dress-shine-stars">✦　·　✧　·　✦</div>${profileDressLayerMarkup(current,'profile-dress-preview dress-shine-preview',selection)}<button class="profile-dress-arrow prev dress-shine-arrow" data-action="profile-dress-prev" aria-label="上一套服装">‹</button><button class="profile-dress-arrow next dress-shine-arrow" data-action="profile-dress-next" aria-label="下一套服装">›</button><span class="dress-shine-caption">${categoryMeta[1]} · ${categoryMeta[2]} 点击右侧部件即时换装</span></main><aside class="dress-shine-right"><div class="dress-shine-category-list">${categoryButtons}</div></aside><section class="dress-shine-picker" aria-label="${categoryMeta[1]}部件选择"><header><b>${categoryMeta[2]} ${categoryMeta[1]}</b><small>点击后角色立即换装 · ${Object.keys(selection).filter(k=>selection[k]).length}/5部件</small></header><div class="dress-shine-picker-row">${DRESS_PART_OPTIONS[category]?dressPartPicker(category,selection):'<p class="dress-shine-locked-copy">该分类将在后续版本开放 · 敬请期待</p>'}</div></section><footer class="dress-shine-bottom"><button class="dress-shine-save" data-action="profile-dress-confirm">▣ 保存搭配</button><button class="dress-shine-round" data-action="profile-dress-tool" data-tool="outfit" aria-label="搭配分享">◈</button><button class="dress-shine-round" data-action="profile-dress-tool" data-tool="dress" aria-label="查看穿搭">♧</button></footer></section>`);}
function profileDecor(){openModal('装饰个人空间',`<p class="modal-text">三种免费房间色调，仅改变个人信息页的装饰，不消耗资源、不增加经营收益。</p><div class="profile-decor-grid">${[['cream','奶油香槟'],['rose','柔粉花园'],['lilac','雾紫月光']].map(([id,label])=>`<button data-action="profile-decor-select" data-decor="${id}" class="profile-decor-choice decor-${id} ${game.state.profile.decor===id?'selected':''}" aria-pressed="${game.state.profile.decor===id}"><span>✧</span><b>${label}</b><small>${game.state.profile.decor===id?'使用中':'免费装饰'}</small></button>`).join('')}</div>`);}
function profileLevel(){const s=game.state;openModal('成长等级与升级',`<div class="profile-level-hero"><b>LV ${s.level}</b><span>${profileRank()}</span></div><p class="modal-text">${s.level===30?'已达到试玩30级上限。':'阅历 '+s.xp+' / '+LoopGame.xpNeed(s.level)+'，还需 '+(LoopGame.xpNeed(s.level)-s.xp)+'点阅历。'}<br>玩家等级随阅历自动提升，这里的升级入口不会直接扣钱或新增一套付费升级规则。</p><div class="detail-rows"><div class="row"><span>升级店铺</span><b>每级 +20阅历</b></div><div class="row"><span>首次完成新成衣</span><b>+80阅历</b></div><div class="row"><span>开放星光定制馆</span><b>+120阅历</b></div><div class="row"><span>当前营业收入</span><b>${fmt(game.income())}元/秒</b></div></div><button class="btn full" data-action="profile-manage">前往经营升级</button>`);}
function profileBonus(){const s=game.state;openModal('经营与等级加成',`<p class="modal-text">使用已有数值体系：玩家等级用于成长和版型门槛，不额外叠加未定义的收入倍率。</p>${STORES.filter(x=>s.shops[x.id].open).map(x=>{const shop=s.shops[x.id];return `<section class="profile-bonus-card"><h3>${x.name} · LV ${shop.level}</h3><div class="row"><span>上架成衣加成</span><b>+${shop.business.length*20}%</b></div><div class="row"><span>商场业务加成</span><b>+${Math.round(game.businessBonus(x.id)*100)}%</b></div><div class="row"><span>店员加成</span><b>+${Math.round(game.employeeBonus(x.id)*100)}%</b></div><div class="row"><span>已领奖套装加成</span><b>+${s.setClaims.length*5}%</b></div><div class="row"><span>实际秒收入</span><b>${fmt(game.shopIncome(x.id))}元/秒</b></div></section>`;}).join('')}<button class="btn full" data-action="profile-manage">前往经营</button>`);}
function profileHonors(){const s=game.state;const medals=[['第一缕灵感','研发首张版型',s.blueprints.length>0,Math.min(1,s.blueprints.length)+' / 1'],['亲手裁衣','完成首次亲手制衣',s.crafted.length>0,Math.min(1,s.crafted.length)+' / 1'],['心动收藏家','收藏10件服装',s.owned.length>=10,Math.min(10,s.owned.length)+' / 10'],['舞台初光','完成首次系统评选',s.contest.entries>0,Math.min(1,s.contest.entries)+' / 1'],['百货新篇','开放星光定制馆',s.shops[1].open,s.shops[1].open?'1 / 1':'0 / 1'],['完整的故事','集齐任意一套服装',SETS.some(x=>x.parts.every(id=>s.owned.includes(id))),SETS.filter(x=>x.parts.every(id=>s.owned.includes(id))).length+'套']];openModal('个人荣誉',`<p class="modal-text">荣誉由现有进度自动点亮，仅作成就展示，不重复发放资源。</p><div class="profile-honor-grid">${medals.map(([title,desc,on,n])=>`<article class="profile-honor ${on?'earned':''}"><span>${profileIcon('medal')}</span><b>${title}</b><small>${desc}</small><em>${on?'已点亮':n}</em></article>`).join('')}</div><button class="btn light full" data-action="journal">查看设计手记</button>`);}
async function profileCopy(text,label='玩家ID'){try{if(!navigator.clipboard?.writeText)throw new Error('no clipboard');await navigator.clipboard.writeText(text);toast(label+'已复制');}catch(error){openModal('手动复制'+label,`<p class="modal-text">当前浏览器未允许自动复制，可长按下方内容复制。</p><label class="sr-only" for="profile-copy-value">${esc(label)}</label><textarea id="profile-copy-value" class="profile-copy-value" readonly>${esc(text)}</textarea>`);$('#profile-copy-value').select();}}
function profileInvite(){const local=location.protocol==='file:';const url=local?'':location.origin+'/trial.html?v=0.10#map';openModal('邀请朋友来试玩',`<div class="profile-invite-icon">${profileIcon('share')}</div><h3 class="profile-invite-heading">一起收藏穿搭灵感</h3><p class="modal-text">你的本地ID：${game.state.profile.id}<br>这不是服务器邀请码，不绑定邀请关系，也不发邀请奖励。${local?'<br>当前为离线文件，可把完整试玩包发送给朋友。':'<br>手机请使用同一Wi-Fi地址；127.0.0.1仅适用于这台电脑。不同设备的存档和社区内容不互通。'}</p>${local?'<button class="btn full" data-action="settings">查看进度与试玩说明</button>':`<label class="sr-only" for="profile-share-value">试玩链接</label><textarea id="profile-share-value" class="profile-copy-value" readonly>${esc(url)}</textarea><button class="btn full" data-action="profile-share-copy">复制试玩链接</button>`}`);}
Object.assign(actions,{
 profile:()=>{if(ui.view!=='profile')ui.profileReturn=ui.view;go('profile');},
 'profile-back':()=>go(VALID_VIEWS.includes(ui.profileReturn)&&ui.profileReturn!=='profile'?ui.profileReturn:'map'),
 'profile-edit':profileEdit,'profile-avatar':profileAvatars,'profile-dress':profileDress,'profile-decor':profileDecor,'profile-level':profileLevel,'profile-bonus':profileBonus,'profile-honors':profileHonors,'profile-invite':profileInvite,
 'profile-avatar-select':e=>{game.updateProfile({avatar:Number(e.dataset.model)});closeModal();toast('个人头像已更新');},
 'profile-look-select':e=>{game.updateProfile({displaySet:e.dataset.set});closeModal();toast('个人展示已更新，衣橱与评选搭配不变');},
 'profile-part-select':e=>{const slot=e.dataset.partSlot,id=Number(e.dataset.partId),def=PROFILE_PART_SLOTS.find(x=>x.slot===slot);if(!def||!def.ids.includes(id))return;const current=profilePartSelections();if(!game.state.owned.includes(id)&&current[slot]!==id)return toast('先在衣橱中获得这个部件');current[slot]=id;game.updateProfile({parts:current});closeModal();profileDress();toast((def.label||'部件')+'已换上');},
 'profile-dress-select':e=>{const id=Number(e.dataset.look);if(!PROFILE_DRESS_LOOKS.some(x=>x.id===id))return;game.updateProfile({dressLook:id});closeModal();profileDress();requestAnimationFrame(()=>document.querySelector('.profile-dress-stage')?.classList.add('camera-switch'));},
 'profile-dress-prev':()=>{const id=Number(game.state.profile.dressLook)||1;const next=id<=1?4:id-1;actions['profile-dress-select']({dataset:{look:String(next)}});},
 'profile-dress-next':()=>{const id=Number(game.state.profile.dressLook)||1;const next=id>=4?1:id+1;actions['profile-dress-select']({dataset:{look:String(next)}});},
 'profile-dress-camera':e=>{const stage=document.querySelector('.profile-dress-stage');if(!stage)return;stage.classList.remove('camera-full','camera-half','camera-detail');stage.classList.add('camera-'+(e.dataset.camera||'full'));document.querySelectorAll('.profile-dress-camera button').forEach(x=>x.classList.toggle('active',x.dataset.camera===e.dataset.camera));},
 'profile-dress-tab':e=>{const tab=e.dataset.tab;document.querySelectorAll('.profile-dress-tabs button').forEach(x=>x.classList.toggle('active',x.dataset.tab===tab));document.querySelectorAll('[data-dress-panel]').forEach(x=>x.classList.toggle('hidden',x.dataset.dressPanel!==tab));},
'profile-dress-confirm':()=>{closeModal();toast('当前造型已保存');},
 'profile-dress-part':e=>{const slot=e.dataset.partSlot||'',idx=PROFILE_DRESS_LOOKS.findIndex(x=>x.id===Number(game.state.profile.dressLook));const next=PROFILE_DRESS_LOOKS.slice(idx+1).concat(PROFILE_DRESS_LOOKS.slice(0,idx+1)).find(x=>x.parts[slot]);if(!next)return toast('该分类暂无其它可替换部件');game.updateProfile({dressLook:next.id});closeModal();profileDress();toast('已换上'+next.name+'的'+slot+'部件');},
 'profile-dress-catalog':()=>toast('敬请期待'),
 'profile-dress-reward':()=>toast('集齐5个部件后可领取套装奖励'),
 'profile-dress-score':()=>{closeModal();go('contest');},
 'profile-dress-attrs':()=>toast('敬请期待'),
  'profile-dress-category':e=>{document.querySelectorAll('.dress-shine-category').forEach(x=>x.classList.toggle('active',x.dataset.category===e.dataset.category));const target=document.querySelector('.dress-shine-part[data-dress-category="'+e.dataset.category+'"]');if(target){target.scrollIntoView({block:'nearest',behavior:'smooth'});target.classList.add('category-focus');setTimeout(()=>target.classList.remove('category-focus'),700);}else if(!['top','bottom','shoes','accessory'].includes(e.dataset.category))toast('该分类为试玩展示，更多内容敬请期待');},
  'profile-dress-tool':e=>{const labels={camera:'拍照功能',favorite:'收藏搭配',new:'新品衣橱',settings:'换装设置',undo:'撤销上一步',redo:'恢复上一步',delete:'删除搭配',search:'搜索服装',like:'喜欢这套搭配',outfit:'分享搭配',dress:'查看穿搭'};toast((labels[e.dataset.tool]||'换装工具')+' · 试玩功能');},
 'profile-collect':e=>{ui.set=e.dataset.set;go('catalog');},
 'profile-decor-select':e=>{game.updateProfile({decor:e.dataset.decor});closeModal();toast('个人空间装饰已保存');},
 'profile-manage':()=>go('map'),'profile-copy':()=>profileCopy(game.state.profile.id),
 'profile-share-copy':()=>profileCopy($('#profile-share-value').value,'试玩链接'),
 'profile-daily':()=>{if(game.state.daily.gift){toast('今日补给已领取，明天再来看看');return;}actions.daily();},
 'profile-club':()=>openModal('名媛会',`<p class="modal-text">试玩版暂未接入真实社团和多人账号，当前名媛会为「暂无」。不会显示虚假成员、入会奖励或联网状态。</p><button class="btn full" data-action="profile-community">去穿搭社区看看</button>`),
 'profile-community':()=>{ui.communityPage='feed';ui.communityFilter='discover';ui.communityTheme='all';ui.view='contest';location.hash='contest';closeModal();render();},
 'profile-help':()=>openModal('你的个人空间',`<p class="modal-text">点击头像可选择个人头像；点击昵称或生日可修改资料。<br>换装使用预制套装展示，除默认形象外需先集齐对应套装。装饰只改变房间色调。<br>阅历、收入和荣誉来自真实试玩进度；本地ID只用于辨认当前存档，不是在线账号。</p><button class="btn full" data-action="close">知道啦</button>`)
});
 actions['profile-dress']=profileDressV2;
 actions['profile-dress-select']=e=>{const id=Number(e.dataset.look);if(!PROFILE_DRESS_LOOKS.some(x=>x.id===id))return;ui.dressUndo=[];ui.dressRedo=[];ui.dressCategory='top';game.updateProfile({dressLook:id,dressParts:dressPresetParts(id)});profileDressV2();toast('已换上'+profileDressLook(id).name);};
 actions['profile-dress-prev']=()=>{const id=Number(game.state.profile.dressLook)||1;actions['profile-dress-select']({dataset:{look:String(id<=1?4:id-1)}});};
 actions['profile-dress-next']=()=>{const id=Number(game.state.profile.dressLook)||1;actions['profile-dress-select']({dataset:{look:String(id>=4?1:id+1)}});};
  actions['profile-dress-part']=e=>{const category=e.dataset.dressCategory,option=DRESS_PART_OPTIONS[category]?.find(x=>(x.src||'')===(e.dataset.partSrc||''));if(!option)return;ui.dressCategory=category;const message=option.src?`已换上${option.name}`:`已恢复基础${DRESS_CATEGORY_META.find(x=>x[0]===category)?.[1]||'部件'}`;applyDressSelection({...profileDressSelections(),[category]:option.src||''},message,true,option.look||game.state.profile.dressLook||1);};
 actions['profile-dress-category']=e=>{ui.dressCategory=e.dataset.category;if(DRESS_PART_OPTIONS[ui.dressCategory])profileDressV2();else toast('该分类将在后续版本开放 · 敬请期待');};
 actions['profile-dress-preset']=()=>{const preset=dressPresetForSelection(profileDressSelections())||0;const next=preset>=4?1:preset+1;actions['profile-dress-select']({dataset:{look:String(next)}});};
 actions['profile-dress-reset']=()=>{const preset=dressPresetForSelection(profileDressSelections())||Number(game.state.profile.dressLook)||1;actions['profile-dress-select']({dataset:{look:String(preset)}});};
  actions['profile-dress-tool']=e=>{const tool=e.dataset.tool;if(tool==='undo'){const previous=ui.dressUndo.pop();if(!previous)return toast('已经是最初搭配');const current=profileDressSelections();ui.dressRedo=[...ui.dressRedo,{selection:current,look:game.state.profile.dressLook}];const selection=previous.selection||previous,look=Number(previous.look||dressPresetForSelection(selection)||1);game.updateProfile({dressParts:selection,dressLook:look});profileDressV2();return toast('已撤销上一件换装');}if(tool==='redo'){const next=ui.dressRedo.pop();if(!next)return toast('没有可恢复的换装');const current=profileDressSelections();ui.dressUndo=[...ui.dressUndo,{selection:current,look:game.state.profile.dressLook}];const selection=next.selection||next,look=Number(next.look||dressPresetForSelection(selection)||1);game.updateProfile({dressParts:selection,dressLook:look});profileDressV2();return toast('已恢复换装');}const labels={camera:'拍照功能',favorite:'收藏搭配',new:'新品衣橱',settings:'换装设置',delete:'清空当前分类',search:'搜索服装',like:'喜欢这套搭配',outfit:'分享搭配',dress:'查看穿搭'};toast((labels[tool]||'换装工具')+' · 试玩功能');};
document.addEventListener('submit',event=>{if(event.target.id!=='profile-edit-form')return;event.preventDefault();try{const month=$('#profile-month').value,day=$('#profile-day').value;if(Boolean(month)!==Boolean(day))throw new Error('请选择完整的生日月日，或同时选择未设置');const birthday=month?month.padStart(2,'0')+'-'+day.padStart(2,'0'):'';game.updateProfile({nickname:$('#profile-nickname-input').value,birthday});closeModal();toast('个人资料已保存');}catch(error){$('#profile-edit-error').textContent=error.message;}});















/* Store interior, NPC scenes, employee assignment and customer story presentation. */
const EMP=FashionEmployees,shopScenes=new Map();let sceneFrame=0,sceneStamp=0;
const GUESTS=[{name:'小悠',sprite:0,story:'周末想和朋友逛花园，想要一件轻松又明亮的新衣。'},{name:'顾然',sprite:1,story:'第一次参加朋友的聚会，希望穿得干净利落一点。'},{name:'林夕',sprite:2,story:'为新的工作日准备一件衣服，想让日常也有一点心动。'},{name:'安娜',sprite:3,story:'这次晚宴想试试不一样的自己，温柔也可以很耀眼。'},{name:'周周',sprite:4,story:'准备给重要的人一个惊喜，希望这份心意能被看见。'},{name:'珊珊',sprite:5,story:'好久没有认真为自己挑新衣了，今天想改变一下。'}];
function shopSprite(sprite,extra=''){return `<span class="shop-sprite ${extra}" style="background-image:url('${asset('boutique-people-atlas-v1.webp')}');background-position:${sprite%3*50}% ${Math.floor(sprite/3)*100}%" aria-hidden="true"></span>`;}
function guestForItem(id,variant){const d=game.orderDemand(Number(id),variant);return {...d.guest,story:d.story};}
function specialItem(shop){const s=game.state;if(s.activeOrder&&FASHION[s.activeOrder.item].store===shop)return s.activeOrder.item;return game.orderOffers().find(d=>FASHION[d.item].store===shop)?.item??(shop===0?3:16);}
function managementViewTabs(){return `<div class="management-view-tabs"><button data-action="management-view" data-mode="interior" class="${ui.managementView!=='city'?'selected':''}">${icon('store')}店内经营</button><button data-action="management-view" data-mode="city" class="${ui.managementView==='city'?'selected':''}">百货总览</button><button data-action="scene-toggle" aria-pressed="${!ui.scenePaused}" aria-label="${ui.scenePaused?'开启':'暂停'}顾客动态">${ui.scenePaused?'动态已暂停':'顾客动态 · 开'}</button></div>`;}
function renderMap(){if(ui.managementView==='city')return managementViewTabs()+renderCityMap();const s=game.state,id=ui.shop||0,shop=s.shops[id],item=specialItem(id),guest=guestForItem(item),assigned=s.employees.assignments[id],staffCount=assigned.filter(Boolean).length;return `<div class="management-title"><div><small>MY LITTLE FASHION BOUTIQUE</small><h1>我的百货城</h1></div><button class="management-daily" data-action="daily" aria-label="领取每日补给">${icon('gift')}${noticeSlot('daily')}</button><button class="management-help" data-action="management-help" aria-label="店内经营说明">?</button></div>${managementViewTabs()}<div class="shop-tabs boutique-tabs">${STORES.map((x,i)=>`<button class="shop-tab ${id===i?'active':''}" data-action="shop-tab" data-id="${i}">${x.name}${s.shops[i].open?'':' · 待开放'}</button>`).join('')}</div><section class="mall-mobile boutique-interior ${shop.open?'':'boutique-locked'}" aria-label="${STORES[id].name}店内经营" data-scene-shop="${id}" style="--boutique:url('${asset('boutique-interior-v1.webp')}')"><div class="boutique-scene-title"><span>${shop.open?'营业中':'等待开业'}</span><b>LV ${shop.level}</b><small>${shop.open?'顾客购物与营业演出':'开放后顾客与雇员会进店'}</small></div><div class="boutique-float"><button class="float-btn order-entry" data-action="orders" aria-label="制衣订单，${s.activeOrder?'制作中':'查看顾客委托'}">${icon('orders')}<b>制衣订单</b><small>${s.activeOrder?'制作中':s.blueprints.length?'可接待':'待研发'}</small>${noticeSlot('orders','订单已完成，可交付领奖')}</button><button class="float-btn employee-entry" data-action="employees" data-shop="${id}" aria-label="${STORES[id].name}雇员系统">${profileIcon('rank')}<b>雇员</b><small>${staffCount}/${s.level>=12?4:3}人</small></button></div>${shop.open?`<div class="shop-npc-layer" aria-label="店内移动的顾客与雇员">${Array.from({length:5},(_,i)=>`<button class="shop-npc guest-npc" data-action="npc-guest" data-npc="${i}" data-shop="${id}" data-visitor="visitor-${i}" aria-label="查看顾客${['小悠','林夕','安娜','顾然','周周'][i]}的购物状态">${shopSprite(i)}<span class="npc-bubble" hidden></span><span class="npc-click-bubble" hidden></span></button>`).join('')}${assigned.map((who,slot)=>{const p=EMP.person(who);return p?`<button class="shop-npc employee-npc" data-action="employees" data-shop="${id}" data-employee="${who}" data-slot="${slot}" aria-label="${EMP.ROLES[slot].name}雇员${p.name}">${shopSprite(p.sprite)}<span class="npc-role-label">${EMP.ROLES[slot].name}</span></button>`:'';}).join('')}${deliveryNpcHtml(id)}<button class="shop-npc special-npc" data-action="special-guest" data-shop="${id}" data-item="${item}" aria-label="特殊顾客${guest.name}的制衣委托">${shopSprite(guest.sprite)}<span class="npc-exclamation">${s.activeOrder?'…':'!'}</span><span class="npc-special-name">${guest.name} · ${s.activeOrder?'制衣中':'有委托'}</span></button></div><div class="shop-event-ribbon" role="status"><span class="event-dot"></span><span id="shop-event-copy">欢迎光临，今天也想遇见一件心动的新衣。</span></div>`:`<div class="boutique-lock-note">${icon('lock')}<b>下一间心动小店</b><span>先完成首店经营与成衣研发</span></div>`}</section><section class="collect-dock"><div><small>店铺收入 · 离线也积累</small><b><span id="income-live">${fmt(game.income())}</span><small> 元/秒</small></b></div><button class="btn" data-action="claim-bank">收取 <span id="bank-amount">${fmt(s.bank)}</span>${icon('coin')}${noticeSlot('bank','营业金可收取')}</button></section><div class="boutique-events"><button data-action="shop-events">${profileIcon('help')}店内事件</button><span>购物表现计入营业收益，不重复发金币</span></div><div class="shop-panel">${storeCard(id)}</div>${s.lastDelivery?`<button class="delivery-memory" data-action="last-customer">${shopSprite(guestForItem(s.lastDelivery.item,s.lastDelivery.demand?.variant??0).sprite)}<span><b>上次交付 · ${FASHION[s.lastDelivery.item].name}</b><small>顾客的心意已送达，查看订单反馈</small></span>${icon('arrow')}</button>`:''}<div class="metrics-strip"><div class="metric"><b>${s.blueprints.length}</b><span>研发版型</span></div><div class="metric"><b>${s.crafted.length}</b><span>首制成衣</span></div><div class="metric"><b>${s.owned.length}/25</b><span>永久收藏</span></div><div class="metric"><b>${s.employees.owned.length}/6</b><span>已招募雇员</span></div></div>${game.loopSteps().every(Boolean)&&!s.loopClaimed?`<button class="btn sage full" data-action="claim-loop">领取首轮闭环奖励 · 2,500元 + 25券${noticeSlot('loop')}</button>`:''}`;}
function sceneFor(shop){if(!shopScenes.has(shop))shopScenes.set(shop,new ShopTraffic.Scene(shop));return shopScenes.get(shop);}
function paintShopScene(scene){const snap=scene.snapshot();for(const g of snap.guests){const el=document.querySelector(`[data-visitor="${g.id}"]`);if(!el)continue;el.style.left=g.x+'%';el.style.top=g.y+'%';el.style.zIndex=String(Math.floor(g.y));el.classList.toggle('walking',g.moving&&!ui.scenePaused);el.dataset.phase=g.label;el.dataset.x=g.x.toFixed(3);el.dataset.y=g.y.toFixed(3);el.querySelector('.shop-sprite').style.transform=`scaleX(${g.facing})`;const bubble=el.querySelector('.npc-bubble');bubble.hidden=g.phase!==5&&g.phase!==2;bubble.textContent=g.phase===5?'谢谢，下次再来♡':'这件真好看';syncNpcClickFeedback(el);}
 const row=game.state.employees.assignments[scene.shop];row.forEach((id,slot)=>{const el=document.querySelector(`[data-employee="${id}"]`);if(!el||!id)return;const a=scene.staffPoints?.[slot]||EMP.ROLES[slot].point,t=(scene.elapsed+slot*2)%12,w=slot!==3?Math.sin(t/12*Math.PI*2):0;el.style.left=(a[0]+w*3)+'%';el.style.top=(a[1]+w*2)+'%';el.style.zIndex=String(Math.floor(a[1]));el.classList.toggle('walking',slot!==3&&!ui.scenePaused);});
 const departing=$('.delivery-npc');if(departing){const until=Number(departing.dataset.deliveryUntil),r=Math.min(1,Math.max(0,(Date.now()-(until-14000))/14000));departing.style.left=(77-r*68)+'%';departing.style.top=(78+r*17)+'%';departing.style.zIndex='95';departing.classList.toggle('walking',!ui.scenePaused);if(r>=1)departing.remove();}
 const copy=$('#shop-event-copy');if(copy&&scene.events.length&&copy.dataset.event!==String(scene.events[0].id)){copy.textContent=scene.events[0].text;copy.dataset.event=String(scene.events[0].id);}const special=$('.special-npc');if(special){const pos=scene.specialPoint||[45,81];special.style.left=pos[0]+'%';special.style.top=pos[1]+'%';special.style.zIndex=String(Math.max(110,Math.floor(pos[1])));}}
const NPC_QUIPS={
 '小悠':['这件版型要是能顺便修饰黑眼圈，我立刻下单！','买手说这色能卖，我先确认它能不能显白。'],
 '顾然':['版型很稳，像我今天的情绪——暂时没有崩。','这件衣服的肩线，比我的工作计划靠谱。'],
 '林夕':['供应链说面料到了，我的灵感还在路上。','通勤要体面，最好还能装下三杯咖啡。'],
 '安娜':['晚宴可以迟到，礼服的气场不能迟到。','这件高光够亮，刚好照出我的加班黑眼圈。'],
 '周周':['再加一点蝴蝶结，浪漫预算还没有超支。','买手请放心，我只试穿，不把整家店搬走。'],
 '珊珊':['今天的上新目标：先让自己心动，再让顾客心动。','这件颜色很会说话，比我开会时有说服力。']
};
function syncNpcClickFeedback(el){const bubble=el.querySelector('.npc-click-bubble');if(!bubble)return;const active=Number(el.dataset.feedbackUntil||0)>Date.now();bubble.hidden=!active;bubble.textContent=active?(el.dataset.feedbackText||''):' ';el.classList.toggle('is-click-feedback',active);if(!active){delete el.dataset.feedbackUntil;delete el.dataset.feedbackText;}}
function showNpcClickFeedback(e){if(Number(e.dataset.feedbackUntil||0)>Date.now())return;const shop=Number(e.dataset.shop),index=Number(e.dataset.npc),scene=sceneFor(shop),g=scene.snapshot().guests[index];if(!g)return;const lines=NPC_QUIPS[g.name]||['这件设计很有灵感，先让我原地心动三秒。'];const text=lines[Math.floor(Math.random()*lines.length)];e.dataset.feedbackUntil=String(Date.now()+2400);e.dataset.feedbackText=g.name+'：'+text;ui.sceneTouchUntil=Date.now()+2400;syncNpcClickFeedback(e);paintShopScene(scene);toast(g.name+'：'+text);}
function mountShopScene(){cancelAnimationFrame(sceneFrame);sceneFrame=0;sceneStamp=0;const root=$('[data-scene-shop]');if(ui.view!=='map'||ui.managementView==='city'||!root||!game.state.shops[Number(root.dataset.sceneShop)].open)return;const scene=sceneFor(Number(root.dataset.sceneShop));scene.paused=!!ui.scenePaused;paintShopScene(scene);const frame=time=>{if(ui.view!=='map'||!root.isConnected)return;if(!document.hidden&&!modal.open&&!ui.scenePaused&&Date.now()>=(ui.sceneTouchUntil||0)){const dt=sceneStamp?Math.min(.12,Math.max(0,(time-sceneStamp)/1000)):0;scene.advance(dt);paintShopScene(scene);}sceneStamp=time;sceneFrame=requestAnimationFrame(frame);};sceneFrame=requestAnimationFrame(frame);}
function specialGuest(shop,item,requestKey=null){const s=game.state;if(!s.shops[shop]?.open)return toast('先开放这间店铺');if(s.activeOrder){ui.orderList=false;return go('customer');}const d=requestKey?game.orderOffers().find(v=>v.item===item&&v.key===requestKey):game.orderDemand(item);if(!d)return toast('订单需求已更新，请重新选择');const x=FASHION[item],guest=d.guest,ready=s.blueprints.includes(item);openModal('特殊顾客 · '+guest.name,`<div class="guest-dialogue"><div class="guest-dialogue-art">${shopSprite(guest.sprite)}</div><div><span>${d.occasion} · 一份只属于她的心意</span><h3>${guest.name}</h3><p>${d.story}</p><blockquote>“${esc(d.request)}”</blockquote></div></div><div class="guest-commission"><div>${photo(item)}</div><span><b>${x.name}</b><small>${d.tags.join(' / ')} · ${d.quantity}件 · ${d.fee}元材料费</small></span><em>${ready?'版型已解锁':'等待工作台研发'}</em></div><p class="modal-text">${ready?orderRewardText(d)+'。接单后选择版型、配色、草图并交付；材料费仅支付一次，取消全退。':'先在工作台研发对应版型，再回来接待顾客；不会跳过研发或直接发放服装。'}</p><div class="modal-actions"><button class="btn light" data-action="close">稍后接待</button><button class="btn" data-action="${ready?'accept-special':'guest-research'}" data-item="${item}" ${requestKey?`data-request="${requestKey}"`:''}>${ready?'接受委托':'前往研发'}</button></div>`);}
function employeeLocation(id){for(let shop=0;shop<2;shop++){const slot=game.state.employees.assignments[shop].indexOf(id);if(slot>=0)return {shop,slot};}return null;}
function openEmployees(shop=ui.shop||0){shop=Number(shop);const s=game.state;if(!s.shops[shop]?.open)return toast('先开放这家店，再派驻雇员');ui.staffShop=shop;const row=s.employees.assignments[shop];openModal(STORES[shop].name+' · 雇员',`<div class="employee-summary"><span>店铺雇员收入加成 <b>+${Math.round(game.employeeBonus(shop)*100)}%</b></span><span>雇员 ${row.filter(Boolean).length}/4人</span></div><div class="employee-roles">${EMP.ROLES.map((role,slot)=>{const p=EMP.person(row[slot]),open=EMP.slotOpen(s,shop,slot);return `<button class="employee-role ${open?'':'locked'} ${p?'occupied':''}" data-action="${open?'employee-roster':'employee-unlock'}" data-shop="${shop}" data-slot="${slot}"><div class="employee-portrait">${p?shopSprite(p.sprite):`<span class="employee-plus">${open?'+':icon('lock')}</span>`}</div><div class="employee-role-copy"><span class="employee-role-title">${role.name}</span><b>${p?p.name:open?'伙伴 · 待委派':'玩家等级达到12级解锁'}</b><small>${p?'效果：本店收入 +'+game.employeeRate(p.id)+'%':open?role.description+' · 委派后提升本店收入':'当前 '+s.level+' / 12级'}</small>${!open?`<span class="employee-unlock-progress"><i style="width:${Math.min(100,s.level/12*100)}%"></i></span>`:''}</div><span class="employee-role-arrow">${open?'›':'↗'}</span></button>`;}).join('')}</div><p class="employee-rules-note">同一雇员只能在一家店的一个岗位工作；调岗会从原岗位撤下。岗位加成相加，招募与派驻分开。</p><button class="btn full" data-action="employee-roster" data-shop="${shop}" data-slot="0">雇员名单与招募</button>`);}
function renderEmployeeRoster(shop,slot=0){shop=Number(shop);ui.staffShop=shop;if(!ui.staffDraft||ui.staffDraft.shop!==shop)ui.staffDraft={shop,row:game.state.employees.assignments[shop].slice(),slot:Number(slot)};else ui.staffDraft.slot=Number(slot);const s=game.state,draft=ui.staffDraft,row=draft.row,bonus=row.reduce((n,id)=>n+(id?game.employeeRate(id):0),0);openModal('雇员名单 · 选择派驻',`<div class="employee-summary"><span>待确认收入加成 <b>+${bonus}%</b></span><span>${row.filter(Boolean).length}/4人</span></div><p class="employee-roster-sub">当前选择：${EMP.ROLES[draft.slot].name} · 点按或拖动雇员到上方岗位</p><div class="employee-assignment-bar">${EMP.ROLES.map((r,i)=>{const who=EMP.person(row[i]),open=EMP.slotOpen(s,shop,i);return `<button class="employee-slot-chip ${draft.slot===i?'active':''}" data-action="employee-slot" data-shop="${shop}" data-slot="${i}" data-drop-slot="${i}" ${open?'':'disabled'} aria-label="${r.name}${who?'已选择'+who.name:open?'空岗位':'未解锁'}">${who?shopSprite(who.sprite):`<span>${open?'+':icon('lock')}</span>`}<small>${r.name}</small></button>`;}).join('')}</div><h3 class="employee-group-heading">已招募的伙伴 <small>点击选择或从当前岗位撤下</small></h3><div class="employee-roster-grid">${EMP.PEOPLE.filter(p=>s.employees.owned.includes(p.id)).map(p=>{const assigned=row.includes(p.id),where=employeeLocation(p.id);return `<button class="employee-person ${assigned?'selected':''}" data-action="employee-select" data-employee="${p.id}" data-drag-source="employee" aria-label="${p.name}，可点按或拖动到岗位" aria-pressed="${assigned}"><div class="employee-person-art">${shopSprite(p.sprite)}</div><b>${p.name}</b><small>${p.tag}</small><em>收入 +${game.employeeRate(p.id)}%</em><span>${assigned?'已选择':where?'在'+STORES[where.shop].name+' · 选择将调岗':'待派驻'}</span></button>`;}).join('')||'<div class="employee-empty">还没有雇员，先招募一位伙伴吧。</div>'}</div><h3 class="employee-group-heading">尚未招募的伙伴</h3><div class="employee-recruit-list">${EMP.PEOPLE.filter(p=>!s.employees.owned.includes(p.id)).map(p=>{const reason=EMP.reason(s,p.id);return `<article class="employee-recruit ${reason?'locked':''}"><div class="employee-recruit-art">${shopSprite(p.sprite)}</div><div><b>${p.name} <small>${p.tag}</small></b><p>${p.bio}</p><span>本店收入 +${game.employeeRate(p.id)}% · ${reason||fmt(p.cost)+'元招募费'}</span></div><button class="btn small" data-action="employee-recruit" data-employee="${p.id}" ${reason?'disabled':''}>${reason?'未解锁':'招募'}</button></article>`;}).join('')||'<p class="employee-rules-note">六位雇员已全部招募。</p>'}</div><div class="employee-confirm-dock"><button class="btn light" data-action="employee-discard" data-shop="${shop}">取消选择</button><button class="btn" data-action="employee-confirm" data-shop="${shop}">确认派驻</button></div><p class="employee-rules-note">选择不会立即改变收入；确认后生效。招募会即时支付经营金币，取消选择不退招募费用。</p>`);}
function shopEvents(){const shop=ui.shop||0,scene=sceneFor(shop),state=scene.snapshot();openModal('店内事件',`<p class="modal-text">${ui.scenePaused?'当前顾客动态已暂停。':'顾客正在进店、选购、排队、结账与离店。'}<br>这是经营表现事件，不是额外金币来源；营业和离线收益仍按店铺秒收入结算。</p><div class="shop-event-list">${state.events.map(e=>`<article>${shopSprite(e.sprite)}<div><b>${e.kind==='sale'?'购物完成':'新客到店'}</b><p>${e.text}</p></div></article>`).join('')||'<p class="modal-text">等待第一位顾客进店。</p>'}</div><button class="btn full" data-action="special-guest" data-shop="${shop}" data-item="${specialItem(shop)}">查看特殊顾客委托</button>`);}
const originalCustomerRenderer=renderCustomer;
function blueprintDetails(id){const x=FASHION[id],info=game.researchInfo(id),s=game.state,known=s.blueprints.includes(id),reason=known?'':game.researchReason(id),have=game.count(info.c,info.t),ready=!known&&!reason&&have>=info.n&&s.coins>=info.cost&&s.seals>=info.seals;ui.recipe=id;render();openModal('版型研发 · '+x.name,`<div class="guest-commission"><div>${photo(id)}</div><span><b>${x.name}</b><small>${TYPE_NAMES[x.type]} · ${x.color} · ${x.tags.join(' / ')}</small></span><em>${known?'已研发':'待研发'}</em></div><div class="detail-rows"><div class="row"><span>${CHAINS[info.c].name} T${info.t+1}</span><b>${have}/${info.n}件</b></div><div class="row"><span>研发资金</span><b>${fmt(s.coins)} / ${fmt(info.cost)}元</b></div>${info.seals?`<div class="row"><span>设计印章</span><b>${s.seals}/${info.seals}</b></div>`:''}</div><p class="modal-text">${known?'版型永久解锁，可以接待对应顾客委托。':reason||'合成对应样衣并筹齐研发资金后，解锁这款服装的顾客订单。'}<br>研发消耗样衣和所列资源，不直接发放成衣。</p><div class="modal-actions"><button class="btn light" data-action="close">返回工作台</button><button class="btn" data-action="${known?'orders':'research'}" data-id="${id}" ${!known&&!ready?'disabled':''}>${known?'查看顾客委托':ready?'研发版型':'研发条件未齐'}</button></div>`);}
function orderRewardText(d){return d.firstCraft?'首制奖励 '+fmt(d.coins)+'元 + '+d.vouchers+'券 · 本店业务 +20%':d.rewarded?'交付奖励 '+fmt(d.coins)+'元 + '+d.vouchers+'券':'今日重复奖励已达10次 · 本单无金币/券奖励';}
function orderDemandCard(d){const x=FASHION[d.item],active=game.state.activeOrder,busy=!!active,current=busy&&active.demand.key===d.key;return `<article class="demand-card ${current?"is-active":""}" data-demand="${d.key}" data-item="${d.item}"><header class="demand-author">${shopSprite(d.guest.sprite)}<div><b>${d.guest.name}</b><small>${d.occasion} · 专属定制</small></div><span class="demand-badge ${d.firstCraft?"is-first":""}">${current?"制作中":d.firstCraft?"待首制":"回访"}</span></header><p class="demand-quote">“${esc(d.request)}”</p><div class="demand-garment">${photo(d.item)}<div><h3>${x.name}</h3><p>${d.typeName} · ${d.color} · ${d.quantity}件</p><small>${d.tags.join(" / ")}</small></div></div><p class="demand-reward ${d.rewarded?"":"is-capped"}">${orderRewardText(d)}</p><footer><button class="text-btn" data-action="guest-story" data-item="${d.item}" data-request="${d.key}">听她说</button><button class="btn small" data-action="take-order" data-id="${d.item}" data-request="${d.key}" ${busy?"disabled":""}>${busy?(current?"当前订单制作中":"先完成当前订单"):"接单 · "+fmt(d.fee)+"元"}</button></footer></article>`;}
function blueprintDemandCard(d){const x=FASHION[d.item],info=game.researchInfo(d.item),open=d.known&&!d.reason,busy=!!game.state.activeOrder;return `<article class="blueprint-demand ${d.known?"is-known":"is-locked"}" data-blueprint="${d.item}"><div class="blueprint-demand-art">${photo(d.item)}<span>${open?"已研发":d.known?"店铺待开":"待研发"}</span></div><div class="blueprint-demand-copy"><h3>${x.name}</h3><p>${d.color} · ${d.typeName} · ${d.tags.join(" / ")}</p><small>需求：${d.occasion} · ${d.quantity}件</small><p class="blueprint-unlock-rule">${open?orderRewardText(d):esc(d.reason||"可研发")+" · "+CHAINS[info.c].name+" T"+(info.t+1)+" ×"+info.n+" / "+fmt(info.cost)+"元"+(info.seals?" / "+info.seals+"印章":"")}</p><button class="${open?"btn light small":"text-btn"}" data-action="${open?"take-order":"order-research"}" data-id="${d.item}" ${open&&busy?"disabled":""}>${open?(busy?"先完成当前订单":"按此版型接单 · "+fmt(d.fee)+"元"):"去工作台查看研发"}</button></div></article>`;}
function renderOrderBoard(){const s=game.state,offers=game.orderOffers(),blueprints=game.blueprintDemands(),match=d=>ui.orderType==='all'||d.type===ui.orderType,visible=(ui.orderTab==='blueprints'?blueprints:offers).filter(match),previews=blueprints.filter(d=>!d.known&&match(d)).slice(0,3),o=s.activeOrder,active=o?game.orderDemand(o.item):null;return `<div class="order-breadcrumb"><button class="text-btn" data-action="nav" data-view="map">‹ 返回经营</button><span>经营功能 · 版型委托</span></div>`+heading('BLUEPRINT ORDER DESK','制衣订单','不同版型，遇见不同的穿衣心愿。',`<span class="pill pink">已交付 ${s.ordersDone} 单</span>`)+`<section class="order-board"><div class="demand-summary"><div><small>顾客委托池</small><b>${offers.length}<span>份顾客需求</span></b></div><div><small>研发成长</small><b>${s.blueprints.length}<span>/ 25 款版型</span></b></div></div>${active?`<section class="order-resume-bar"><div><b>${active.guest.name} · ${FASHION[o.item].name}</b><small>${active.occasion} · ${["选择版型","确认配色","绘制草图","挑选成衣"][o.stage]} · 材料费已支付</small></div><button class="btn small" data-action="order-resume">继续制作</button></section>`:""}<div class="order-board-tabs" role="tablist" aria-label="订单类型"><button role="tab" aria-selected="${ui.orderTab==="offers"}" data-action="order-tab" data-tab="offers">顾客委托 <span>${offers.length}</span></button><button role="tab" aria-selected="${ui.orderTab==="blueprints"}" data-action="order-tab" data-tab="blueprints">版型需求 <span>25</span></button></div><div class="order-type-filters" role="group" aria-label="按版型品类筛选">${[["all","全部"],...Object.entries(TYPE_NAMES)].map(([type,name])=>`<button class="chip ${ui.orderType===type?"active":""}" data-action="order-filter" data-type="${type}" aria-pressed="${ui.orderType===type}">${name}</button>`).join("")}</div><p class="order-board-note">${ui.orderTab==="blueprints"?"需求预告不代表已解锁；研发对应版型后，才能支付材料费接单。":"交付后自动更新委托 · 一次制作一单 · 材料费只付一次，取消全退"}</p><div class="${ui.orderTab==="blueprints"?"blueprint-demand-list":"demand-grid"}">${visible.map(ui.orderTab==="blueprints"?blueprintDemandCard:orderDemandCard).join("")||`<div class="order-empty"><b>${offers.length?"当前品类暂无顾客委托":"先研发一款版型，开启顾客委托"}</b><p>${offers.length?"切换品类，或在版型需求中查看其它款式。":"女装样衣9+1合成到T2，再研发粉色披肩礼服；即可出现3份不同场景的委托。"}</p><button class="btn light" data-action="${offers.length?"order-tab":"order-research"}" data-tab="blueprints" data-id="3">${offers.length?"查看版型需求":"去研发首款版型"}</button></div>`}</div>${ui.orderTab==="offers"&&previews.length?`<section class="upcoming-demands"><header><div><small>NEXT BLUEPRINTS</small><h2>顾客还在期待这些款式</h2></div><button class="text-btn" data-action="order-tab" data-tab="blueprints">全部25款 ›</button></header>${previews.map(blueprintDemandCard).join("")}</section>`:""}<p class="order-economy-note">首制永久收藏并增加本店业务收入；重复制衣奖励每日最多10次，当前剩余 ${Math.max(0,10-s.daily.repeats)} 次。同款不同场景不生成新的服装或颜色。</p></section>`;}
renderCustomer=function(){const o=game.state.activeOrder;if(!o||ui.orderList)return renderOrderBoard();const d=game.orderDemand(o.item);let html=originalCustomerRenderer();html=html.replace(/<span class="guest-avatar">[^<]+<\/span>/,`<span class="guest-avatar portrait-guest">${shopSprite(d.guest.sprite)}</span>`).replace(/<div class="bubble">[\s\S]*?<\/div>/,`<div class="bubble">${d.guest.name}：${esc(d.request)}<small>顾客订单 #${o.id} · 材料费已支付 · 取消可退还</small></div>`);return html.replace('<div class="craft-steps">',`<div class="customer-story-line">“${d.story}”<span>${d.occasion} · ${d.typeName} · ${d.color} · ${d.quantity}件</span></div><div class="active-demand-meta"><span>${orderRewardText(d)}</span><button class="text-btn" data-action="order-list">‹ 订单列表</button></div><div class="craft-steps">`);};
const originalReceipt=receipt;
receipt=function(result){originalReceipt(result);const variant=result.demand?.variant??0,guest=guestForItem(result.item,variant);$('.success-title')?.insertAdjacentHTML('beforebegin',`<div class="customer-delivery-story"><div>${shopSprite(guest.sprite)}</div><p><b>${guest.name} · 交付反馈</b><span>“这件${FASHION[result.item].name}正是我想要的，谢谢你把心意做成了新衣！”</span></p></div>`);$('.modal-actions')?.insertAdjacentHTML('beforeend',`<button class="btn light" data-action="order-list">查看下一份委托</button><button class="btn light" data-action="delivery-shop" data-item="${result.item}">回店送别顾客</button>`);ui.deliveredGuest={item:result.item,variant,until:Date.now()+14000};};
Object.assign(actions,{
 'management-view':e=>{ui.managementView=e.dataset.mode;render();},
 'scene-toggle':()=>{ui.scenePaused=!ui.scenePaused;render();toast(ui.scenePaused?'顾客动态已暂停，营业收益正常结算':'顾客动态已开启');},
 employees:e=>{ui.staffDraft=null;openEmployees(Number(e.dataset.shop??ui.shop??0));},
 'employee-roster':e=>renderEmployeeRoster(Number(e.dataset.shop),Number(e.dataset.slot||0)),
 'employee-slot':e=>renderEmployeeRoster(ui.staffShop,Number(e.dataset.slot)),
 'employee-select':e=>{const id=e.dataset.employee,d=ui.staffDraft;if(!d)return;if(!EMP.slotOpen(game.state,d.shop,d.slot))return toast('此岗位尚未解锁');if(d.row[d.slot]===id)d.row[d.slot]=null;else{d.row=d.row.map(who=>who===id?null:who);d.row[d.slot]=id;}renderEmployeeRoster(d.shop,d.slot);},
 'employee-recruit':e=>{const d=ui.staffDraft,p=game.recruitEmployee(e.dataset.employee);renderEmployeeRoster(d.shop,d.slot);toast('已招募'+p.name+'，点击她的卡片再确认派驻');},
 'employee-discard':e=>{ui.staffDraft=null;openEmployees(Number(e.dataset.shop));},
 'employee-confirm':e=>{const d=ui.staffDraft;if(!d)return;game.setEmployees(d.shop,d.row);const shop=d.shop;ui.staffDraft=null;openEmployees(shop);toast('雇员已到岗，秒收入同步更新');},
 'employee-unlock':()=>openModal('收银岗位 · 等级解锁',`<p class="modal-text">玩家达到12级后解锁第四个岗位。当前等级 ${game.state.level}/12。<br>升级店铺、研发版型和首次制衣会获得阅历，岗位解锁不额外收费。</p><button class="btn full" data-action="profile-manage">前往经营升级</button>`),
 'special-guest':e=>specialGuest(Number(e.dataset.shop),Number(e.dataset.item)),
 'guest-story':e=>specialGuest(FASHION[Number(e.dataset.item)].store,Number(e.dataset.item),e.dataset.request||null),
 'guest-research':e=>{ui.recipe=Number(e.dataset.item);go('work');},
 'accept-special':e=>{ui.orderList=false;game.takeOrder(Number(e.dataset.item),e.dataset.request||null);go('customer');toast('已接受顾客委托，材料费仅支付一次');},
 'take-order':e=>{ui.orderList=false;game.takeOrder(Number(e.dataset.id),e.dataset.request||null);go('customer');},
 orders:()=>{ui.orderList=false;ui.orderTab='offers';ui.orderType='all';go('customer');},
 'order-list':()=>{ui.orderList=true;if(!game.state.activeOrder){ui.orderTab='offers';ui.orderType='all';}go('customer');},
 'order-resume':()=>{ui.orderList=false;go('customer');},
 'order-tab':e=>{ui.orderTab=e.dataset.tab==='blueprints'?'blueprints':'offers';render();},
 'order-filter':e=>{ui.orderType=Object.hasOwn(TYPE_NAMES,e.dataset.type)?e.dataset.type:'all';render();},
 'order-research':e=>{ui.recipe=Number(e.dataset.id);go('work');},
 'blueprint-detail':e=>blueprintDetails(Number(e.dataset.id)),
 'npc-guest':e=>showNpcClickFeedback(e),
 'shop-events':shopEvents,
 'delivery-shop':e=>{ui.shop=FASHION[Number(e.dataset.item)].store;ui.managementView='interior';go('map');},
 'last-customer':()=>receipt(game.state.lastDelivery),
 'management-help':()=>openModal('经营与顾客事件',`<p class="modal-text">顾客会进店、选购、排队、结账后离店。点击普通顾客可查看状态；带「！」的特殊顾客会提出制衣委托。<br>雇员按接待、货架、会员服务、收银四岗位派驻，会在对应区域服务。先招募、再选择岗位并确认，才会增加店铺收入。<br>普通购物演出不重复发金币；真实订单和离线营业仍沿用原有结算。可暂停动态，或查看百货总览。</p><button class="btn full" data-action="close">开始营业</button>`)
});
if(ui.scenePaused===undefined)ui.scenePaused=matchMedia('(prefers-reduced-motion: reduce)').matches;
window.addEventListener('pagehide',()=>cancelAnimationFrame(sceneFrame));
const originalStoreCard=storeCard;
storeCard=function(id){let html=originalStoreCard(id);const n=game.state.employees.assignments[id].filter(Boolean).length;return html.replace(/<button class="text-btn" data-action="hire"[\s\S]*?<\/button>/,`<button class="text-btn" data-action="employees" data-shop="${id}">雇员 ${n}/4 · 加成+${Math.round(game.employeeBonus(id)*100)}%</button>`).replace('店员已到岗',n+'位雇员在岗').replace('店员待招募','雇员待派驻');};
storeModal=function(id){const shop=game.state.shops[id],def=STORES[id];openModal(def.name+' · 经营加成',`<div class="detail-rows"><div class="row"><span>等级基础收入</span><b>${fmt(game.baseIncome(id)+def.step*(shop.level-1))}元/秒</b></div><div class="row"><span>已上架款式</span><b>+${shop.business.length*20}%</b></div><div class="row"><span>商场业务加成</span><b>+${Math.round(game.businessBonus(id)*100)}%</b></div><div class="row"><span>雇员岗位加成</span><b>+${Math.round(game.employeeBonus(id)*100)}%</b></div><div class="row"><span>已领奖套装</span><b>+${game.state.setClaims.length*5}%</b></div><div class="row"><span>实际收入</span><b>${fmt(game.shopIncome(id))}元/秒</b></div></div><p class="modal-text">公式：等级基础收入 ×（1 + 已上架款式 + 商场业务 + 已派驻雇员 + 已领奖套装）。仅作用于当前店铺，普通购物演出不再次发金币。</p><button class="btn full" data-action="employees" data-shop="${id}">管理这家店的雇员</button>`);};

function deliveryNpcHtml(shop){const d=ui.deliveredGuest;if(!d||Date.now()>=d.until||FASHION[d.item].store!==shop)return '';return `<button class="shop-npc delivery-npc" data-action="last-customer" data-delivery-until="${d.until}" aria-label="送别${guestForItem(d.item,d.variant??0).name}">${shopSprite(guestForItem(d.item,d.variant??0).sprite)}<span class="npc-bubble">新衣很合心意，谢谢你♡</span></button>`;}

// Hold a moving target briefly while the finger completes its tap.
document.addEventListener('pointerdown',event=>{const guest=event.target.closest('.guest-npc');if(guest){ui.sceneTouchUntil=Date.now()+2400;showNpcClickFeedback(guest);return;}if(event.target.closest('.shop-npc'))ui.sceneTouchUntil=Date.now()+1200;},true);

/* V0.10 mall layout: full scene + shop strip + expansion/upgrade dock. */
const MALL=FashionMall;
function mallBusinessName(b){return (b.id<25?'':'精选 · ')+FASHION[b.art].name+(b.kind==='base'?'陈列':'专柜');}
function mallNumber(value){if(value>=1e8)return(value/1e8).toFixed(2)+'亿';if(value>=1e4)return(value/1e4).toFixed(1)+'万';return Math.floor(value).toLocaleString('zh-CN');}
function mallSceneMarkup(shop){ui.managementView='interior';const source=renderBoutiqueMap();const box=document.createElement('div');box.innerHTML=source;const scene=box.querySelector('.boutique-interior');scene.querySelector('.boutique-float')?.remove();scene.querySelector('.boutique-scene-title')?.remove();scene.querySelector('.shop-event-ribbon')?.remove();const s=game.state,exp=game.expansionInfo(shop);scene.insertAdjacentHTML('beforeend',`<div class="mall-left-tools"><button class="mall-round-tool mall-bank" data-action="claim-bank" aria-label="领取营业金">${icon('coin')}<b>营业金</b><small id="bank-amount">${mallNumber(s.bank)}</small>${noticeSlot('bank','营业金可收取')}</button><button class="mall-round-tool" data-action="daily" aria-label="领取每日补给">${icon('gift')}<b>每日补给</b>${noticeSlot('daily')}</button></div><button class="mall-appearance" data-action="profile-dress" aria-label="修改个人展示形象">${icon('hanger')}<b>形象改造</b></button><div class="mall-right-tools"><button class="mall-round-tool order-entry" data-action="orders" aria-label="商场订单">${icon('orders')}<b>商场订单</b><small>${s.activeOrder?'制作中':game.orderOffers().length?game.orderOffers().length+'份委托':'待研发'}</small>${noticeSlot('orders')}</button><button class="mall-round-tool business-entry" data-action="mall-business" data-shop="${shop}" aria-label="店铺业务">${icon('book')}<b>业务</b><span class="mall-business-dot" ${mallAvailableBusiness(shop)?'':'hidden'}></span></button><button class="mall-round-tool employee-entry" data-action="employees" data-shop="${shop}" aria-label="雇佣员工">${shopSprite(0)}<b>员工</b><small>${s.employees.assignments[shop].filter(Boolean).length}/4</small></button></div><button class="mall-order-goal" data-action="orders" aria-label="累计完成20次紧急订单，已完成${Math.min(20,s.ordersDone)}次"><span>!</span><div><b>累计完成20次紧急订单</b><i><em style="width:${Math.min(100,s.ordersDone/20*100)}%"></em><small>${Math.min(20,s.ordersDone)}/20</small></i></div><strong>›</strong></button><button class="mall-scene-event" data-action="shop-events" aria-label="查看顾客移动事件"><span id="shop-event-copy">今天也想遇见一件心动的新衣。</span></button>${exp.stage>0?`<span class="mall-expanded-tag">${exp.stage===1?'新陈列区':'高定体验区'} · 业务容量${MALL.CAPACITIES[exp.stage]}</span>`:''}`);return scene.outerHTML;}
function mallAvailableBusiness(shop){return MALL.BUSINESS.filter(b=>!game.businessReason(shop,b.id)).length;}
function storyRouteSummary(route){return route?`${route.name} · ${route.buyer}`:'尚未选择买手路线';}
function storyMaterialSummary(st){return `<span class="story-material-chip">布料 <b>${st.materials.fabric}</b></span><span class="story-material-chip">辅料 <b>${st.materials.trim}</b></span><span class="story-material-chip">稀有 <b>${st.materials.rare}</b></span>`;}
function storyStageDots(p){return p.stages.map(x=>{const active=x.id===p.stage,done=x.id==='brief'?Boolean(p.st.selectedRoute):x.id==='material'?Boolean(p.st.selectedSupplier):x.id==='design'?p.st.flags.includes('design'):x.id==='order'?p.st.flags.includes('order'):x.id==='feedback'?p.st.flags.includes('delivery'):p.st.flags.includes('publish');return `<span class="story-stage-dot ${active?'active':''} ${done&&!active?'done':''}" title="${x.label}"></span>`;}).join('');}
function renderStoryCard(){const p=game.storyProgress(),s=p.st,story=game.storyFeedback(),route=p.route,supplier=p.supplier;const action=p.stage==='brief'?'story-brief':p.stage==='material'?'story-material':p.stage==='design'?'nav':p.stage==='order'||p.stage==='feedback'?'nav':'nav';const view=p.stage==='design'?'work':p.stage==='order'||p.stage==='feedback'?'customer':'community';const actionText=p.stage==='brief'?'查看AI经营简报':p.stage==='material'?'选择供应链材料':p.stage==='design'?'去工作台打样':p.stage==='order'?'去完成商城订单':p.stage==='feedback'?'查看顾客反馈':'去发布穿搭日记';return `<section class="story-command-card" aria-label="设计经营主线"><div class="story-card-head"><div><span class="story-kicker">AI经营主线 · 第${s.chapter}章</span><h2>${s.chapter===1?'接手旧店':'品牌转折 · 第'+s.chapter+'章'}</h2></div><span class="story-reputation">声望 ${story.reputation}</span></div><div class="story-role-row"><span>设计师 LV${story.designerRank}</span><span>买手 LV${story.buyerRank}</span><span>供应链 ${supplier?'已接入':'待选择'}</span></div><div class="story-progress-track" aria-label="主线进度">${storyStageDots(p)}</div><div class="story-stage-label"><b>${p.stageLabel}</b><small>${s.lastFeedback||'把客群、材料和设计串成一次上新。'}</small></div><div class="story-route-line"><span>买手路线</span><b>${storyRouteSummary(route)}</b></div><div class="story-route-line"><span>供应链</span><b>${supplier?supplier.name:'等待采购材料'}</b></div><div class="story-material-row">${storyMaterialSummary(s)}</div><div class="story-card-actions"><button class="btn small sage" data-action="${action}" ${action==='nav'?`data-view="${view}"`:''}>${actionText}${icon('arrow')}</button><button class="text-btn" data-action="story-feedback">查看反馈</button></div></section>`;}
function renderStoryMiniCard(){const p=game.storyProgress(),s=p.st;return `<section class="story-mini-card" aria-label="当前经营主线"><span class="story-mini-label">主线 ${s.chapter} · ${p.stageLabel}</span><b>${s.selectedRoute?storyRouteSummary(p.route):'先确定买手路线，再把材料带进工作台'}</b><small>${s.lastFeedback||'经营决策会影响材料、订单和上新反馈。'}</small><div>${storyMaterialSummary(s)}<button class="text-btn" data-action="story-feedback">查看主线</button></div></section>`;}
function storyBriefModal(){const brief=game.storyBrief(),p=game.storyProgress();openModal(brief.title,`<div class="story-dialog-hero"><span>AI编剧 · 经营简报</span><b>${brief.body}</b><small>本章目标：选客群 → 采购材料 → 工作台打样 → 完成订单 → 发布穿搭日记</small></div><div class="story-choice-title">买手判断</div><div class="story-route-grid">${STORY_ROUTES.map(x=>{const locked=x.id==='premium'&&game.state.level<4;return `<button class="story-route-choice ${locked?'locked':''}" data-action="story-route" data-route="${x.id}" ${locked?'disabled':''}><span>${x.name}</span><b>${x.buyer}</b><small>采购预算 ${x.cost}元 · 主题 ${THEMES.find(t=>t.id===x.theme)?.name||'新品上新'}</small><em>${locked?'设计师4级开放':x.feedback}</em></button>`}).join('')}</div><p class="modal-text">路线只影响本章的材料与反馈方向，不会永久锁死玩法；完成一章后可以重新选择。${p.route?`当前已选：${p.route.name}`:''}</p>`);}
function storyMaterialModal(){const p=game.storyProgress();if(!p.route)return storyBriefModal();openModal('采购材料 · 接入供应链',`<div class="story-dialog-hero"><span>买手路线 · ${p.route.name}</span><b>${p.route.buyer}</b><small>选择供应商后，材料会进入当前主线，并在工作台与订单中持续提示。</small></div><div class="story-route-grid">${STORY_ROUTES.map(x=>{const locked=x.id==='premium'&&game.state.level<4;return `<button class="story-route-choice ${locked?'locked':''}" data-action="story-procure" data-supplier="${x.id}" ${locked?'disabled':''}><span>${x.name}</span><b>${x.id===p.route.id?'同路线 · 风险较低':'跨路线采购 · 可换取不同风格'}</b><small>支付 ${x.cost}元 · 布料+${x.materials.fabric} · 辅料+${x.materials.trim} · 稀有+${x.materials.rare}</small><em>${locked?'设计师4级开放':x.feedback}</em></button>`}).join('')}</div><p class="modal-text">当前经营资金：${fmt(game.state.coins)}元。完成采购后可直接去工作台，研发与交付会推进本章剧情。</p>`);}
function storyFeedbackModal(){const x=game.storyFeedback();openModal('主线反馈 · '+x.stage,`<div class="story-feedback-card"><div class="story-feedback-metrics"><b>声望 ${x.reputation}</b><span>设计师 LV${x.designerRank}</span><span>买手 LV${x.buyerRank}</span></div><p>“${esc(x.feedback)}”</p><div class="story-route-line"><span>买手路线</span><b>${esc(x.route)}</b></div><div class="story-route-line"><span>供应链</span><b>${esc(x.supplier)}</b></div><div class="story-material-row"><span class="story-material-chip">布料 <b>${x.materials.fabric}</b></span><span class="story-material-chip">辅料 <b>${x.materials.trim}</b></span><span class="story-material-chip">稀有 <b>${x.materials.rare}</b></span></div></div><button class="btn full" data-action="story-primary">继续主线</button>`);}
Object.assign(actions,{
 'story-brief':storyBriefModal,
 'story-material':storyMaterialModal,
 'story-feedback':storyFeedbackModal,
 'story-primary':()=>{const p=game.storyProgress();closeModal();if(p.stage==='brief')return storyBriefModal();if(p.stage==='material')return storyMaterialModal();if(p.stage==='design')return go('work');if(p.stage==='order'||p.stage==='feedback')return go('customer');go('community');},
 'story-route':e=>{try{game.chooseStoryRoute(e.dataset.route);storyMaterialModal();toast('买手路线已确定，下一步选择供应链');}catch(err){toast(err.message);}},
 'story-procure':e=>{try{game.procureStoryMaterial(e.dataset.supplier);closeModal();go('work');toast('材料已进入主线，工作台目标已同步');}catch(err){toast(err.message);}},
 'story-advance':e=>{try{game.advanceStory(e.dataset.trigger);render();toast('主线反馈已更新');}catch(err){toast(err.message);}}
});
const renderBoutiqueMap=renderMap;
renderMap=function(){const s=game.state,id=ui.shop||0,shop=s.shops[id],def=STORES[id],info=game.expansionInfo(id),upgrade=game.upgradeCost(id,ui.mallFast?10:1),other=shop.business.length*.2+game.employeeBonus(id)+s.setClaims.length*.05+game.businessBonus(id);const expansionHint=info.max?'已达试玩上限':info.ready?'资金 '+mallNumber(info.cost):info.businessReady?info.gateLabel:'业务 '+info.count+'/'+info.need;return `<section class="mall-shell" aria-label="商场经营"><div class="mall-main-scene">${mallSceneMarkup(id)}</div><div class="mall-shop-strip"><button class="mall-shop-name" data-action="mall-shops">${icon('store')}<b>${def.name}</b><span>${shop.level}级</span></button><button class="mall-income-info" data-action="store-detail" data-id="${id}" aria-label="查看收入加成">i</button><span class="mall-shop-income">${icon('coin')}<b id="mall-shop-income">${mallNumber(game.shopIncome(id))}元/秒</b></span><button class="mall-income-info" data-action="mall-help" aria-label="商场经营说明">i</button></div><div class="mall-control-panel"><div class="mall-income-copy"><span>基础收入：<b>${mallNumber(game.baseIncome(id)+def.step*(shop.level-1))}元/秒</b><small>（每级+${def.step}元）</small></span><span>其他加成：<b id="mall-other-bonus">${other.toFixed(2)}倍</b></span><button class="mall-back" data-action="mall-shops" aria-label="返回商场店铺列表">${profileIcon('back')}</button><button class="mall-guidance" data-action="${mission().index===5&&!s.loopClaimed?'claim-loop':'guide'}">${mission().index<5?'首轮目标 '+Math.min(5,mission().index+1)+'/5':(s.loopClaimed?'设计闭环':'领取闭环奖励')} ›${noticeSlot('loop')}</button></div><div class="mall-growth-actions"><div><button class="mall-expand" data-action="mall-expand" data-shop="${id}" ${!shop.open||info.max?'disabled':''}>拓展${info.ready?'<span>+1</span>':''}</button><small>${expansionHint}</small><em>${info.max?'':'解锁后提产'}</em></div><div><button class="mall-upgrade" data-action="mall-upgrade" data-shop="${id}" ${!shop.open||!upgrade.n?'disabled':''}>升级${noticeSlot('mall-upgrade:'+id,'商城经营可升级')}</button><small>${upgrade.n?icon('coin')+mallNumber(upgrade.cost):'等级已满'}</small><label class="mall-fast-upgrade"><input type="checkbox" data-mall-fast ${ui.mallFast?'checked':''}>快速升级</label></div></div></div></section>${renderStoryCard()}`;};
function openMallShops(){openModal('我的商场 · 店铺',`<div class="mall-shop-list">${STORES.map(x=>{const s=game.state.shops[x.id];return `<article><div>${icon('store')}<b>${x.name}</b><small>${s.open?'营业中 · '+s.level+'级':'待开业 · 完成首店与研发门槛'}</small></div><button class="btn" data-action="${s.open?'mall-shop-select':'open-store'}" data-shop="${x.id}">${s.open?'进入经营':'开放店铺'}</button></article>`;}).join('')}</div><p class="modal-text">服装商店使用新视频的可确认数据校准；星光定制馆保留试玩的基础收入配置。拓展店铺区域与开放第二家店是两项不同操作。</p>`);}
function openMallBusiness(shop=ui.shop||0,tab=ui.mallBusinessTab||'base'){shop=Number(shop);ui.mallBusinessShop=shop;ui.mallBusinessTab=tab;const s=game.state,ids=s.mall.business[shop],capacity=MALL.CAPACITIES[s.mall.expansion[shop]],list=MALL.BUSINESS.filter(b=>tab==='base'?b.kind==='base':b.kind==='expanded');openModal(tab==='base'?'基础业务':'拓展业务',`<div class="mall-business-summary"><span>店铺名称：<b>${STORES[shop].name}</b></span><span>${tab==='base'?'基础':'拓展'}业务加成：<b>${ids.filter(id=>MALL.BUSINESS[id].kind===tab).reduce((sum,id)=>sum+MALL.businessRate(s,shop,id),0)}%</b></span></div><p class="mall-business-hint">已拓展业务为绿色，可拓展业务会发光提示；灰色业务需要先完成等级或区域条件。</p><div class="mall-business-grid">${list.map(b=>{const owned=ids.includes(b.id),reason=owned?'':game.businessReason(shop,b.id),inArea=b.id<capacity,available=!owned&&inArea&&!reason,stateClass=owned?'unlocked':available?'available':!inArea?'unexpanded':'locked',status=owned?'已拓展':available?'可拓展':!inArea?'待拓展':'未解锁';return `<button class="mall-business-card ${stateClass}" data-action="mall-business-open" data-shop="${shop}" data-business="${b.id}" aria-label="${mallBusinessName(b)}，${status}"><span class="mall-business-status">${status}</span><img src="${art(b.art)}" alt="${mallBusinessName(b)}业务示意图" draggable="false"><b>${mallBusinessName(b)}</b><small>${owned?'✓ 已拓展 · +'+MALL.businessRate(s,shop,b.id)+'%':available?'✦ 点击拓展 · +5%':!inArea?'拓展区域后开放':reason}</small></button>`;}).join('')}</div><div class="mall-business-tabs"><button data-action="mall-business-tab" data-tab="base" class="${tab==='base'?'selected':''}">基础业务</button><button data-action="mall-business-tab" data-tab="expanded" class="${tab==='expanded'?'selected':''}">拓展业务</button></div>`);}
function mallBusinessOpen(shop,id){const s=game.state,b=MALL.BUSINESS[id];if(s.mall.business[shop].includes(id))return openModal('经营业务 · '+mallBusinessName(b),`<div class="detail-art">${photo(b.art)}</div><p class="modal-text">这项业务已解锁，为${STORES[shop].name}增加${MALL.businessRate(s,shop,id)}%收入。不会重复解锁或领奖，也不代表永久拥有图中的服装。</p><button class="btn full" data-action="mall-business" data-shop="${shop}">返回业务</button>`);const reason=game.businessReason(shop,id);if(reason)return openModal('业务解锁条件',`<div class="detail-art">${photo(b.art)}</div><p class="modal-text">${mallBusinessName(b)}<br>解锁条件：${reason}。<br>达到条件后可免费解锁，收入+${b.bonus}%。</p><button class="btn full" data-action="${id>=MALL.CAPACITIES[s.mall.expansion[shop]]?'mall-expand':'mall-close-business'}" data-shop="${shop}">${id>=MALL.CAPACITIES[s.mall.expansion[shop]]?'前往拓展':'返回店铺升级'}</button>`);game.unlockBusiness(shop,id);openModal('恭喜 · 新业务解锁',`<div class="mall-business-celebration"><div class="mall-rays">✧</div>${photo(b.art)}<p>成功解锁新的业务 <b>${mallBusinessName(b)}</b></p><strong>${STORES[shop].name}收入 +${b.bonus}%</strong></div><button class="btn full" data-action="mall-business" data-shop="${shop}">继续查看业务</button>`);toast('业务已解锁，收入提升'+b.bonus+'%');}
function openMallExpansion(shop){shop=Number(shop);const i=game.expansionInfo(shop),goal=i.goal||{},s=game.state,hasJournal=Boolean(s.community&&Array.isArray(s.community.posts)&&s.community.posts.length)||Boolean(s.contest&&s.contest.entries);const gateRows=!i.max?`<div class="row"><span>店铺等级</span><b>${game.state.shops[shop].level}/${goal.shopLevel||'-'}级</b></div><div class="row"><span>玩家等级</span><b>${s.level}/${goal.playerLevel||'-'}级</b></div><div class="row"><span>顾客订单</span><b>${s.ordersDone}/${goal.orders||'-'}笔</b></div><div class="row"><span>研发版型</span><b>${s.blueprints.length}/${goal.blueprints||'-'}张</b></div>${goal.secondShop?`<div class="row"><span>星光定制馆</span><b>${s.shops[1].open?'已开放':'未开放'}</b></div>`:''}${goal.employee?`<div class="row"><span>雇员派驻</span><b>${s.shops[shop].staff?'已派驻':'未派驻'}</b></div>`:''}${goal.journal?`<div class="row"><span>穿搭日记</span><b>${hasJournal?'已发布':'未发布'}</b></div>`:''}`:'';openModal('店铺拓展',`<div class="mall-expansion-hero">${icon('store')}<b>第${i.stage+1}区 ${i.max?'· 已拓展完成':'→ 第'+(i.stage+2)+'区'}</b></div><div class="detail-rows"><div class="row"><span>业务解锁进度</span><b>${i.count}/${i.need}</b></div><div class="row"><span>当前业务容量</span><b>${MALL.CAPACITIES[i.stage]}项</b></div>${!i.max?`<div class="row"><span>拓展后可经营</span><b>${i.nextCapacity}项业务</b></div><div class="row"><span>拓展资金</span><b>${mallNumber(i.cost)}元</b></div><div class="row"><span>收入积累目标</span><b>约${i.targetMinutes}分钟</b></div>${gateRows}`:''}</div><p class="modal-text">${i.max?'已达到本试玩的区域上限。':i.ready?'阶段条件已满足，可以使用经营资金拓展。':i.businessReady?'业务已集齐，还需要：'+i.gateLabel+'。':'先解锁当前区域的全部业务，再完成阶段目标。'}<br>拓展不会直接授予服装，新增区域会开放新的业务容量。</p><div class="modal-actions"><button class="btn light" data-action="mall-business" data-shop="${shop}">查看业务</button><button class="btn" data-action="mall-confirm-expand" data-shop="${shop}" ${i.ready?'':'disabled'}>${i.max?'已完成':i.ready?'确认拓展':'条件未达标'}</button></div>`);}
function mallFunds(required){const s=game.state;openModal('资金不足 · 获取途径',`<div class="mall-funds-summary">${icon('coin')}<div><b>经营资金</b><span>拥有：${mallNumber(s.coins)} / <em>${mallNumber(required)}</em></span></div></div><button class="settings-action" data-action="mall-claim-and-close">营业金<small>可收取 ${mallNumber(Math.floor(s.bank))}元 · 离线也会积累</small></button><button class="settings-action" data-action="mall-daily-and-close">每日补给<small>${s.daily.gift?'今日已领取':'可领取1,200元、10券和体力'}</small></button><button class="settings-action" data-action="orders">商场订单<small>完成真实制衣委托获得试玩奖励</small></button><p class="modal-text">没有真实支付或广告，也不显示未接入的购买渠道。订单奖励沿用试玩值，视频未展示其结算页。</p>`);}
function syncMallHUD(){if(ui.view!=='map')return;const id=ui.shop||0;$('#mall-shop-income')?.replaceChildren(document.createTextNode(mallNumber(game.shopIncome(id))+'元/秒'));$('#bank-amount')?.replaceChildren(document.createTextNode(mallNumber(game.state.bank)));}
function renderCommunity(){ui.communityPage='feed';return renderContest();}
const originalGo=go;
go=function(view,opts={}){if(view==='community'||view==='contest')ui.communityPage='feed';originalGo(view,opts);};
function nav(){const active=ui.view==='customer'?'map':ui.view,html=navs.map(([v,label,name])=>`<button class="nav-item ${active===v?'active':''}" data-action="nav" data-view="${v}" ${active===v?'aria-current="page"':''}>${v==='community'?socialIcon('comment'):icon(name)}<span>${label}</span>${noticeSlot('nav:'+v,v==='catalog'?'有新服装或可领取奖励':'有可领取奖励')}</button>`).join('');$('#desktop-nav').innerHTML=html;$('#mobile-nav').innerHTML=html;}
navs.splice(0,navs.length,['map','商场经营','store'],['community','社区','book'],['work','工作台','work'],['contest','穿搭日记','cup'],['catalog','背包','book']);
ui.mallFast=false;ui.mallBusinessTab='base';if(ui.view==='contest')ui.communityPage='feed';
Object.assign(actions,{
 'mall-shops':openMallShops,'mall-shop-select':e=>{ui.shop=Number(e.dataset.shop);go('map');},
 'mall-business':e=>openMallBusiness(Number(e.dataset.shop??ui.shop??0)),
 'mall-business-tab':e=>openMallBusiness(ui.mallBusinessShop,e.dataset.tab),
 'mall-business-open':e=>mallBusinessOpen(Number(e.dataset.shop),Number(e.dataset.business)),
 'mall-close-business':()=>{closeModal();toast('使用底部升级按钮，达到要求等级后再来解锁');},
 'mall-expand':e=>openMallExpansion(Number(e.dataset.shop)),
 'mall-confirm-expand':e=>{const shop=Number(e.dataset.shop),info=game.expansionInfo(shop);if(!info.ready)return openMallExpansion(shop);if(game.state.coins<info.cost)return mallFunds(info.cost);try{game.expandMall(shop);closeModal();toast('店铺已拓展，新业务区开放');}catch(err){toast(err.message);}},
 'mall-upgrade':e=>{const id=Number(e.dataset.shop),count=ui.mallFast?10:1,info=game.upgradeCost(id,count);if(game.state.coins<info.cost)return mallFunds(info.cost);const result=game.upgrade(id,count);toast('店铺提升'+result.n+'级，基础收入增加'+result.n*STORES[id].step+'元/秒');},
 'mall-claim-and-close':()=>{actions['claim-bank']();closeModal();},'mall-daily-and-close':()=>openSigninModal(),
 'mall-help':()=>openModal('商场经营 · 数据说明',`<p class="modal-text">新业务解锁+5%、服装商店每级+3元/秒、连升十级、20次紧急订单目标来自新视频。<br>商城拓展现在与有效经营收入挂钩：每个区域按15/25/40/60/90/120/180/240分钟有效产出计算拓展资金，并同时检查店铺等级、玩家等级、订单和版型研发进度。<br>视频没有打开订单奖励页，制衣订单仍使用原试玩的材料费和奖励，未冒充视频数值。<br>点击特殊顾客或商场订单接待；员工招募后需确认派驻。业务只增加收入，不赠送服装。</p><button class="btn full" data-action="close">知道了</button>`),
 'ugc-compose':()=>{ui.ugcRequestId=game.state.community.draft.id;originalGo('contest');ui.communityPage='compose';render();},
 'ugc-back':()=>{ui.communityPage='feed';ui.communityFilter='discover';ui.communityTheme='all';ui.view='contest';location.hash='contest';closeModal();render();},
 'ugc-discover':()=>{ui.communityPage='feed';ui.communityFilter='discover';ui.communityTheme='all';ui.view='contest';location.hash='contest';closeModal();render();}
});
const originalPublishAction=actions['enter-contest'];actions['enter-contest']=()=>{const before=game.state.community.posts.length;originalPublishAction();if(game.state.community.posts.length>before){ui.view='contest';ui.communityPage='feed';ui.communityFilter='mine';location.hash='contest';}};
document.addEventListener('change',event=>{if(event.target.matches('[data-mall-fast]')){ui.mallFast=event.target.checked;render();}});
const priorShopEvents=actions['shop-events'];actions['shop-events']=()=>{priorShopEvents();modal.insertAdjacentHTML('beforeend',`<button class="btn light full" data-action="scene-toggle">${ui.scenePaused?'开启':'暂停'}顾客动态</button>`);};
actions['scene-toggle']=()=>{ui.scenePaused=!ui.scenePaused;render();closeModal();toast(ui.scenePaused?'顾客动态已暂停，营业收益正常结算':'顾客动态已开启');};
actions['open-store']=()=>{game.openSecond();ui.shop=1;closeModal();go('map');toast('星光定制馆已开放');};

/* V0.21: actual business claims drive layered fixtures; natural portrait scene supports touch scrolling. */
const MALL_V21_PROPS=[
 {key:'window',file:'mall-prop-window-v21.webp',name:'服装橱窗',x:5,y:68,w:30,z:68,ready:(s,id)=>s.shops[id].open},
 {key:'rack',file:'mall-prop-rack-v21.webp',name:'中央衣架',x:27,y:84,w:40,z:84,ready:(s,id)=>s.mall.business[id].includes(0)},
 {key:'mannequin',file:'mall-prop-mannequin-v21.webp',name:'人模展示台',x:62,y:80,w:28,z:80,ready:(s,id)=>s.mall.business[id].includes(1)},
 {key:'lounge',file:'mall-prop-lounge-v21.webp',name:'中层休息区',x:23,y:44,w:43,z:44,ready:(s,id)=>s.mall.business[id].includes(2)},
 {key:'vanity',file:'mall-prop-vanity-v21.webp',name:'妆容体验台',x:6,y:87,w:22,z:87,ready:(s,id)=>s.mall.business[id].includes(3)},
 {key:'shoe',file:'mall-prop-shoe-v21.webp',name:'鞋包精品店',x:72,y:67,w:26,z:67,ready:(s,id)=>s.mall.expansion[id]>=1},
 {key:'wash',file:'mall-prop-wash-v21.webp',name:'洗护服务台',x:2,y:78,w:25,z:78,ready:(s,id)=>s.mall.expansion[id]>=2},
 {key:'bath',file:'mall-prop-bath-v21.webp',name:'生活方式专区',x:67,y:74,w:31,z:74,ready:(s,id)=>s.mall.expansion[id]>=2}
];
function mallV21Fixtures(shop){return MALL_V21_PROPS.filter(p=>p.ready(game.state,shop));}
function mallV21Next(shop){
 const s=game.state,store=s.shops[shop],info=game.expansionInfo(shop),count=s.mall.business[shop].length;
 if(!store.open)return {title:'开放星光定制馆',sub:'首店4级 · 2张版型 · 首制2件成衣',action:'mall-shops'};
 const available=MALL.BUSINESS.find(b=>!game.businessReason(shop,b.id));
 if(count<2&&available)return {title:'解锁 '+mallBusinessName(available),sub:'达到等级后点击解锁 · 新业务收入 +5%',business:available.id};
 if(count>=2&&!s.employees.assignments[shop].some(Boolean))return {title:'为小店安排第一位员工',sub:'招募 → 选择岗位 → 确认派驻',action:'employees'};
 if(!s.blueprints.some(id=>FASHION[id].store===shop)&&store.level>=2)return {title:'研发一张专属版型',sub:'工作台合成样衣，接待特殊顾客',action:'guest-research',item:specialItem(shop)};
 if(!s.crafted.some(id=>FASHION[id].store===shop)&&s.blueprints.some(id=>FASHION[id].store===shop))return {title:s.activeOrder?'完成当前顾客委托':'接待特殊顾客',sub:'版型 → 配色 → 草图 → 成衣交付',action:'orders'};
 if(info.ready)return {title:'拓展新的经营区域',sub:'本区业务已集齐 · 新陈列区即将开放',action:'mall-expand'};
 if(available)return {title:'解锁 '+mallBusinessName(available),sub:'新业务收入 +5% · 解锁后场景同步变化',business:available.id};
 const next=MALL.BUSINESS.find(b=>b.id<MALL.CAPACITIES[info.stage]&&!s.mall.business[shop].includes(b.id));
 return next?{title:'升级到 '+next.minLevel+' 级',sub:'下一项业务：'+mallBusinessName(next),action:'mall-upgrade'}:{title:'继续收集专属新衣',sub:'研发与制衣，为小店上架更多款式',action:'orders'};
}
const mallV21LegacyScene=mallSceneMarkup;
mallSceneMarkup=function(shop){
 const s=game.state,exp=game.expansionInfo(shop),box=document.createElement('div');box.innerHTML=mallV21LegacyScene(shop);
 const scene=box.querySelector('.boutique-interior'),layer=scene.querySelector('.shop-npc-layer'),npcs=layer?.outerHTML||'',lockedNote=scene.querySelector('.boutique-lock-note')?.outerHTML||'';
 layer?.remove();scene.querySelector('.boutique-lock-note')?.remove();scene.classList.add('mall-v21-scene');scene.dataset.mallVersion='0.21';
 const fixtures=mallV21Fixtures(shop),count=Math.min(4,exp.stage+1);
 const props=fixtures.map(p=>`<button class="mall-v21-prop ${p.key}" data-prop="${p.key}" data-action="mall-business" data-shop="${shop}" aria-label="查看${p.name}经营业务" style="left:${p.x}%;top:${p.y}%;width:${p.w}%;z-index:${p.z}"><img src="${asset(p.file)}" alt="${p.name}" draggable="false"><span>${p.name}</span></button>`).join('');
 const boxes=Array.from({length:count},(_,i)=>`<img class="mall-v21-box box-${i+1}" src="${asset('mall-box-'+(i+1)+'-v21.webp')}" alt="待拓展区仓储纸箱" draggable="false">`).join('');
 const next=mallV21Next(shop);
 scene.insertAdjacentHTML('afterbegin',`<div class="mall-v21-pan" tabindex="0" role="region" aria-label="商场楼层，可上下滑动查看"><div class="mall-v21-world"><img class="mall-v21-backdrop" src="${asset('mall-floor-empty-v21.webp')}" alt="商场空场景基础楼层" draggable="false"><div class="mall-v21-boxes">${boxes}</div>${props}${npcs}</div></div>${lockedNote}<div class="mall-v21-scene-title"><b>第${exp.stage+1}经营区</b><span>已开放 ${s.mall.business[shop].length}项业务</span></div><button class="mall-v21-motion-toggle" data-action="mall-v21-motion" aria-pressed="${!ui.scenePaused}" aria-label="${ui.scenePaused?'开启':'暂停'}顾客动态">${ui.scenePaused?'动态已暂停':'顾客动态 · 开'}</button><button class="mall-v21-next" data-action="mall-v21-next" data-shop="${shop}"><span>✦</span><div><small>下一步经营目标</small><b>${esc(next.title)}</b><em>${esc(next.sub)}</em></div><strong>›</strong></button><span class="mall-v21-pan-hint">↕ 上下滑动查看楼层</span>`);
 return scene.outerHTML;
};
const mallV21Mount=mountShopScene;
mountShopScene=function(){
 if(ui.view==='map'){
  const shop=ui.shop||0,scene=sceneFor(shop),rack=game.state.mall.business[shop].includes(0);
  scene.setLayout(rack?[[17,94],[26,86],[38,77],[43,79],[65,83],[76,84],[61,87],[16,95]]:[[17,94],[26,86],[21,70],[25,72],[65,83],[76,84],[61,87],[16,95]]);
  scene.staffPoints=[[22,86],[34,76],[66,80],[79,83]];scene.specialPoint=[52,87];
  const pan=$('.mall-v21-pan');
  if(pan){ui.mallPanY??={};const max=Math.max(0,pan.scrollHeight-pan.clientHeight);pan.scrollTop=Math.min(max,ui.mallPanY[shop]??max);pan.addEventListener('scroll',()=>{ui.mallPanY[shop]=pan.scrollTop},{passive:true});}
 }
 mallV21Mount();
};
const mallV21BusinessOpen=mallBusinessOpen;
mallBusinessOpen=function(shop,id){const before=mallV21Fixtures(shop).map(p=>p.key);mallV21BusinessOpen(shop,id);const added=mallV21Fixtures(shop).filter(p=>!before.includes(p.key));if(added.length&&modal.querySelector('.mall-business-celebration'))modal.querySelector('.mall-business-celebration').insertAdjacentHTML('beforeend',`<div class="mall-v21-new-fixture"><img src="${asset(added[0].file)}" alt="${added[0].name}"><span>场景新增 · ${added[0].name}</span></div>`);};
const mallV21LegacyExpansion=openMallExpansion;
openMallExpansion=function(shop){mallV21LegacyExpansion(shop);const i=game.expansionInfo(Number(shop));modal.querySelector('.mall-expansion-hero')?.insertAdjacentHTML('afterend',`<div class="mall-v21-expansion-preview"><img src="${asset('mall-floor-finished-v21.webp')}" alt="用户提供的完整商城场景参考"><div><b>拓展新区域 · 新陈列与动线</b><span>${i.stage===0?'下一阶段开放鞋包精品店':i.stage===1?'下一阶段开放洗护与生活方式专区':'已开放全部试玩区域'}</span><small>图为素材完整效果参考，实际设施依解锁进度出现。</small></div></div>`);};
const mallV21Sync=syncMallHUD;
syncMallHUD=function(){mallV21Sync();if(ui.view!=='map')return;const id=ui.shop||0,available=mallAvailableBusiness(id);document.querySelector('.mall-business-dot')?.toggleAttribute('hidden',!available);const next=mallV21Next(id),card=$('.mall-v21-next');if(card){card.querySelector('b').textContent=next.title;card.querySelector('em').textContent=next.sub;}};
Object.assign(actions,{
 'mall-v21-motion':()=>actions['scene-toggle'](),
 'mall-v21-next':e=>{const shop=Number(e.dataset.shop),next=mallV21Next(shop);if(next.business!==undefined)return mallBusinessOpen(shop,next.business);const proxy={dataset:{shop:String(shop),item:String(next.item??specialItem(shop))}};return actions[next.action]?.(proxy);}
});

/* V0.22: coordinate-locked five-stage mall floor, based on the supplied complete floor reference. */
const MALL_V22_SLOTS=[
 {stage:1,file:'mall-unlock-1-v30.webp',name:'中心服装展示台',left:26,top:60,width:37,scale:1,z:620},
 {stage:2,file:'mall-unlock-2-v30.webp',name:'生活方式浴缸区',left:55,top:57,width:32,scale:1,z:580},
 {stage:3,file:'mall-unlock-3-v30.webp',name:'化妆饰品台',left:10,top:56,width:35,scale:1,z:620},
 {stage:4,file:'mall-unlock-4-v30.webp',name:'上层服装特卖区',left:58,top:-4,width:36,scale:1,z:120},
 {stage:5,file:'mall-unlock-5-v30.webp',name:'中央人模展台',left:17,top:25,width:42,scale:1,z:300},
 {stage:6,file:'mall-unlock-6-v30.webp',name:'左侧主题橱窗',left:0,top:76,width:17,scale:1,z:520},
 {stage:7,file:'mall-unlock-7-v30.webp',name:'女装鞋履墙',left:-2,top:49,width:37,scale:1,z:360},
 {stage:8,file:'mall-unlock-8-v30.webp',name:'中央休息区',left:56,top:72,width:40,scale:1,z:500}
];
const mallV22LegacyScene=mallV21LegacyScene;
// Keep the supplied artwork's reference coordinates, but render the large booth art
// at a smaller visual scale.  The CSS transform keeps its floor contact point aligned
// while shrinking the pointer footprint with it.
function mallV22Style(slot){return `left:${slot.left}%;top:${slot.top}%;width:${slot.width}%;z-index:${slot.z};--mall-slot-scale:${slot.scale??.78}`;}
function mallV22BoxPosition(slot){return {left:slot.left+slot.width*.31,top:slot.top+slot.width*.22,width:slot.width*.34};}
function mallV22Next(shop){
 const info=game.expansionInfo(shop),stage=info.stage;
 if(stage>=MALL_V22_SLOTS.length)return {title:'商城八个展台已全部开放',sub:'继续经营并接待订单',action:'orders'};
 if(info.ready)return {title:'拓展第'+(stage+1)+'区域',sub:'解锁「'+MALL_V22_SLOTS[stage].name+'」',action:'mall-expand'};
 if(info.businessReady)return {title:'完成第'+(stage+1)+'区阶段条件',sub:info.gateLabel,action:'mall-expand'};
 return {title:'完成第'+(stage+1)+'区业务',sub:'业务 '+info.count+'/'+info.need,action:'mall-business'};
}
function mallV22UnlockedMarkup(shop){
 const stage=game.expansionInfo(shop).stage;
 return MALL_V22_SLOTS.filter(slot=>stage>=slot.stage).map(slot=>`<button class="mall-v22-slot unlocked" data-action="mall-v22-slot" data-slot="${slot.stage}" aria-label="${slot.name}，已解锁" style="${mallV22Style(slot)}"><img src="${asset(slot.file)}" alt="${slot.name}" draggable="false"><span>${slot.name}</span></button>`).join('');
}
function mallV22LockedMarkup(shop){
 const stage=game.expansionInfo(shop).stage;
 return MALL_V22_SLOTS.filter(slot=>slot.stage===stage+1).map(slot=>{const p=mallV22BoxPosition(slot);return `<button class="mall-v22-slot locked" data-action="mall-v22-slot" data-slot="${slot.stage}" aria-label="${slot.name}，未解锁" style="left:${p.left}%;top:${p.top}%;width:${p.width}%;z-index:25"><img src="${asset('mall-locked-box-v30.webp')}" alt="未解锁箱子" draggable="false"><span>第${slot.stage}区未解锁</span></button>`;}).join('');
}
function mallV22SceneMarkup(shop){
 const s=game.state,info=game.expansionInfo(shop),box=document.createElement('div');box.innerHTML=mallV22LegacyScene(shop);
 const scene=box.querySelector('.boutique-interior');if(!scene)return box.innerHTML;
 const npcLayer=scene.querySelector('.shop-npc-layer'),npcs=npcLayer?.outerHTML||'';npcLayer?.remove();
 scene.querySelector('.boutique-scene-title')?.remove();scene.querySelector('.boutique-float')?.remove();scene.querySelector('.shop-event-ribbon')?.remove();scene.querySelector('.boutique-lock-note')?.remove();
 const controls=Array.from(scene.children).filter(el=>!el.matches('.shop-npc-layer,.boutique-lock-note,.boutique-scene-title')).map(el=>el.outerHTML).join('');
 const next=mallV22Next(shop);
 scene.className='boutique-interior mall-v22-scene';scene.dataset.mallVersion='0.22';
 scene.innerHTML=`<div class="mall-v22-pan" tabindex="0" role="region" aria-label="商城场景，可上下左右拖动查看"><div class="mall-v22-world"><img class="mall-v22-backdrop" src="${asset('mall-floor-v30.webp')}" alt="商城夹层空场景" draggable="false"><div class="mall-v22-slots">${mallV22LockedMarkup(shop)}${mallV22UnlockedMarkup(shop)}</div>${npcs}</div></div>${controls}<div class="mall-v22-zone-badge"><b>商城夹层</b><span>第${info.stage+1}区 · 已开放 ${info.stage>=MALL_V22_SLOTS.length?'全部':info.stage+' / '+MALL_V22_SLOTS.length} 个展台</span></div><button class="mall-v22-next" data-action="mall-v22-next" data-shop="${shop}"><span>✦</span><div><small>区域解锁 ${Math.min(info.stage+1,MALL_V22_SLOTS.length)}/${MALL_V22_SLOTS.length}</small><b>${esc(next.title)}</b><em>${esc(next.sub)}</em></div><strong>›</strong></button><span class="mall-v22-pan-hint">↕↔ 拖动查看商城</span>`;
 return scene.outerHTML;
}
mallSceneMarkup=mallV22SceneMarkup;
const mallV22BaseMount=mallV21Mount;
function mallV22InstallPan(pan,shop){
 if(!pan||pan.dataset.v22Ready)return;
 pan.dataset.v22Ready='1';ui.mallPanV22??={};
 const center=()=>{const maxX=Math.max(0,pan.scrollWidth-pan.clientWidth),maxY=Math.max(0,pan.scrollHeight-pan.clientHeight);if(ui.mallPanV22[shop]){pan.scrollLeft=Math.min(maxX,ui.mallPanV22[shop].x);pan.scrollTop=Math.min(maxY,ui.mallPanV22[shop].y);}else{pan.scrollLeft=Math.round(maxX/2);pan.scrollTop=Math.round(maxY/2);}};
 requestAnimationFrame(center);window.setTimeout(center,80);
 pan.addEventListener('scroll',()=>{ui.mallPanV22[shop]={x:pan.scrollLeft,y:pan.scrollTop};},{passive:true});
 let drag=null,suppressClickUntil=0;
 // Start the pan gesture even when the finger lands on a booth. A short tap
 // remains a booth click; only a real move suppresses the delegated action.
 pan.addEventListener('pointerdown',e=>{
  if(e.button!==undefined&&e.button!==0||e.isPrimary===false)return;
  drag={x:e.clientX,y:e.clientY,left:pan.scrollLeft,top:pan.scrollTop,pointerId:e.pointerId,moved:false};
  try{pan.setPointerCapture?.(e.pointerId)}catch{}
  pan.classList.add('dragging');
 },{passive:false});
 pan.addEventListener('pointermove',e=>{
  if(!drag||e.pointerId!==drag.pointerId)return;
  const dx=e.clientX-drag.x,dy=e.clientY-drag.y;
  if(!drag.moved&&Math.hypot(dx,dy)>4)drag.moved=true;
  if(!drag.moved)return;
  pan.scrollLeft=drag.left-dx;pan.scrollTop=drag.top-dy;e.preventDefault();
 },{passive:false});
 const end=e=>{
  if(!drag||e.pointerId!==drag.pointerId)return;
  const moved=drag.moved;drag=null;pan.classList.remove('dragging');
  if(moved){suppressClickUntil=performance.now()+420;pan.dataset.suppressClick='1';e.preventDefault();}
  try{pan.releasePointerCapture?.(e.pointerId)}catch{}
 };
 pan.addEventListener('pointerup',end,{passive:false});pan.addEventListener('pointercancel',end,{passive:false});
 pan.addEventListener('pointerleave',e=>{if(e.buttons===0)end(e)});
 pan.addEventListener('click',e=>{
  if(pan.dataset.suppressClick==='1'||performance.now()<suppressClickUntil){pan.dataset.suppressClick='';suppressClickUntil=0;e.preventDefault();e.stopPropagation();}
 },true);
}
mountShopScene=function(){
 if(ui.view==='map'){
  const shop=ui.shop||0,scene=sceneFor(shop);scene.setLayout([[8,94],[20,90],[43,84],[52,77],[51,54],[70,48],[87,50],[95,37]]);scene.staffPoints=[[24,90],[48,79],[70,49],[91,37]];scene.specialPoint=[51,78];
  mallV22InstallPan(document.querySelector('.mall-v22-pan'),shop);
 }
 mallV22BaseMount();
};
const mallV22LegacyExpansion=openMallExpansion;
openMallExpansion=function(shop){mallV22LegacyExpansion(shop);const info=game.expansionInfo(Number(shop));modal.querySelector('.mall-v21-expansion-preview')?.remove();modal.querySelector('.mall-expansion-hero')?.insertAdjacentHTML('afterend',`<div class="mall-v22-expansion-preview"><b>第${info.stage+1}个展台</b><img src="${asset(MALL_V22_SLOTS[Math.min(info.stage,MALL_V22_SLOTS.length-1)].file)}" alt="${MALL_V22_SLOTS[Math.min(info.stage,MALL_V22_SLOTS.length-1)].name}"><span>确认拓展后，按照顺序解锁「${MALL_V22_SLOTS[Math.min(info.stage,MALL_V22_SLOTS.length-1)].name}」</span></div>`);};
const mallV22OldSync=syncMallHUD;
syncMallHUD=function(){mallV22OldSync();if(ui.view!=='map')return;const card=document.querySelector('.mall-v22-next');if(card){const next=mallV22Next(ui.shop||0);card.querySelector('b').textContent=next.title;card.querySelector('em').textContent=next.sub;}};
Object.assign(actions,{
 'mall-v22-slot':e=>{const slot=MALL_V22_SLOTS[Number(e.dataset.slot)-1];const stage=game.expansionInfo(ui.shop||0).stage;if(stage>=Number(e.dataset.slot))openModal('展台已解锁',`<p class="modal-text">${slot.name}已开放，顾客会经过这里完成浏览、体验和结账。</p><button class="btn full" data-action="close">继续经营</button>`);else openMallExpansion(ui.shop||0);},
 'mall-v22-next':e=>{const next=mallV22Next(Number(e.dataset.shop));if(next.action==='mall-business')return openMallBusiness(Number(e.dataset.shop));if(next.action==='mall-expand')return openMallExpansion(Number(e.dataset.shop));return actions[next.action]?.({dataset:{shop:e.dataset.shop}});}
});




/* V0.11 community hub: city district, contest entry, order/task/store shortcuts and local chat. */
const HALL_KEY='fashion.loop.community.hall.v1';
const HALL_CHANNELS=[['local','本服'],['system','系统'],['club','名媛会'],['private','私聊'],['cross','跨服']];
const HALL_EMOJIS=['😊','😂','🥹','😍','🤍','✨','🌸','👗','💖','👏','🎉','🙈','😎','😭','🤔','🎁'];
const HALL_SEEDS={local:[['系统小助手','今日街区的樱花开了，去市集看看新的搭配灵感吧。','system'],['小花的衣橱','有人一起参加今天的花园午后穿搭日记吗？','user'],['周周搭配日记','我刚收藏了一套粉色礼服，评论区见～','user']],system:[['系统公告','社区互动仅保存于当前试玩，不代表真实在线聊天。','system'],['防骗提示','请勿相信充值、买号、线下交易等信息。','system']],club:[['名媛会会长','本周主题：把春天穿在身上，欢迎大家分享灵感。','user'],['米娅','新衣做好啦，等你们来点赞。','user']],private:[['艾米的搭配助手','这里是你的私聊频道，可以记录穿搭灵感。','system']],cross:[['系统频道','跨服频道为试玩展示，不连接其他玩家。','system']]};
function hallDate(){return new Date(game.now()).toISOString().slice(0,10);}
function hallLoad(){let value=null;try{value=JSON.parse(localStorage.getItem(HALL_KEY)||'null')}catch(e){};const base={version:1,channel:'local',draft:{local:'',system:'',club:'',private:'',cross:''},emojiOpen:false,messages:{},tasks:{date:hallDate(),claimed:[]},store:{date:hallDate(),claimed:{},tab:'packs',watched:'',items:{energy:1,materials:1,boost:1}}};for(const [key,rows] of Object.entries(HALL_SEEDS))base.messages[key]=rows.map((x,i)=>({id:`seed-${key}-${i}`,author:x[0],text:x[1],kind:x[2],at:'示例消息'}));if(value&&value.version===1){Object.assign(base,value);base.messages={...base.messages,...(value.messages||{})};base.tasks=value.tasks||base.tasks;const savedStore=value.store||{};base.store={...base.store,...savedStore,claimed:{...base.store.claimed,...(savedStore.claimed||{})},items:{...base.store.items,...(savedStore.items||{})}}}if(base.tasks.date!==hallDate())base.tasks={date:hallDate(),claimed:[]};if(base.store.date!==hallDate())base.store={...base.store,date:hallDate(),claimed:{},watched:''};if(!base.store.tab)base.store.tab='packs';if(!base.store.items)base.store.items={energy:1,materials:1,boost:1};return base;}
const hallState=hallLoad();
function hallSave(){try{localStorage.setItem(HALL_KEY,JSON.stringify(hallState))}catch(e){}}
function hallChannelLabel(key){return HALL_CHANNELS.find(x=>x[0]===key)?.[1]||'本服';}
function hallMessageRows(key){return hallState.messages[key]||[];}
function hallTaskData(){const s=game.state;return [{id:'login',title:'登录游戏',desc:'进入社区大厅一次',current:1,target:1,reward:'+300元',ready:true,claim:()=>game.tx(x=>{x.coins+=300})},{id:'order',title:'完成制衣订单',desc:'完成一次真实顾客交付',current:Math.min(1,s.ordersDone),target:1,reward:'+5服饰券',ready:s.ordersDone>=1,claim:()=>game.tx(x=>{x.vouchers+=5})},{id:'merge',title:'工作台合成5次',desc:'累计完成工作台合成',current:Math.min(5,s.merges),target:5,reward:'+10体力',ready:s.merges>=5,claim:()=>game.tx(x=>{x.energy=Math.min(100,x.energy+10)})},{id:'social',title:'社区互动3次',desc:'点赞、收藏或评论任意作品',current:Math.min(3,(s.community?.liked?.length||0)+(s.community?.saved?.length||0)+(s.community?.comments?.length||0)),target:3,reward:'+3服饰券',ready:((s.community?.liked?.length||0)+(s.community?.saved?.length||0)+(s.community?.comments?.length||0))>=3,claim:()=>game.tx(x=>{x.vouchers+=3})}];}
function hallStoreIcon(label){const text=String(label||'');const key=text.includes('体力')?'energy':text.includes('券')?'ticket':text.includes('印章')?'star':text.includes('营业')||text.includes('金币')||text.includes('资金')||text.includes('元')?'coin':text.includes('材料')||text.includes('面料')||text.includes('样衣')?'work':text.includes('观影')||text.includes('礼盒')||text.includes('礼包')?'gift':'gift';return icon(key);}
function hallItemTile(label,value,cls=''){return `<span class="hall-item-tile ${cls}"><span class="hall-item-icon">${hallStoreIcon(label)}</span><b>${label}</b><small>${value}</small></span>`;}
function renderCommunity(){const level=Math.max(1,Number(game.state.level)||1),rankUnlocked=level>=10,marketUnlocked=level>=20;const previewRows=hallMessageRows(hallState.channel).slice(-2);while(previewRows.length<2)previewRows.unshift({author:'社区助手',text:'欢迎来到社区聊天，分享你的穿搭灵感。',kind:'system'});return `<section class="community-hall" aria-label="社区大厅" style="--hall-city:url('${asset('community-city-v1.webp')}')"><div class="hall-city-bg"></div><div class="hall-city-wash"></div><header class="hall-heading"><div><small>FASHION CITY COMMUNITY</small><h1>时尚街区</h1><p>穿搭、聊天与故事灵感都在这里相遇。</p></div><button class="hall-help" data-action="community-help" aria-label="社区说明">?</button></header><div class="hall-landmarks"><button data-action="community-home"><span>我的家</span><b>${icon('book')}</b></button><button class="${rankUnlocked?'':'locked'}" data-action="community-rank" data-unlock-level="10" aria-label="${rankUnlocked?'排行榜':'排行榜（10级解锁）'}"><span>排行榜</span><b>${icon('cup')}</b>${rankUnlocked?'':'<small>LV10</small>'}</button><button data-action="community-contest"><span>穿搭日记</span><b>${icon('hanger')}</b></button><button class="${marketUnlocked?'':'locked'}" data-action="community-market" data-unlock-level="20" aria-label="${marketUnlocked?'市集':'市集（20级解锁）'}"><span>市集</span><b>${icon('store')}</b>${marketUnlocked?'':'<small>LV20</small>'}</button></div><div class="hall-top-right"><button class="hall-quick" data-action="community-daily">${icon('gift')}<b>日常任务</b>${hallTaskData().some(x=>x.ready&&!hallState.tasks.claimed.includes(x.id))?'<i></i>':''}</button><button class="hall-quick" data-action="community-store">${icon('store')}<b>商店</b>${(!hallState.store.claimed.free)?'<i></i>':''}</button></div><button class="hall-contest-card" data-action="community-contest"><span class="hall-contest-badge">今日主题</span><b>花园午后 · 穿搭日记</b><small>发布穿搭、评论作品，赢取穿搭日记奖励</small><strong>进入穿搭日记 ›</strong></button><button class="hall-chat-preview" data-action="community-chat"><div class="hall-chat-avatar">${socialIcon('comment')}</div><div><b>社区聊天</b><div class="hall-chat-preview-lines">${previewRows.length?previewRows.map(m=>`<span><em>${esc(m.author||'玩家')}</em> ${esc(m.kind==='look'?'分享了我的服装穿搭':(m.text||''))}</span>`).join(''):`<span>点击打开聊天频道</span>`}</div></div><strong>›</strong></button><button class="hall-order-entry" data-action="orders"><span class="hall-order-alert">!</span><div><b>商场订单</b><small>${game.state.activeOrder?'有正在制作的顾客委托':'查看顾客制衣订单'}</small></div><strong>›</strong>${game.state.activeOrder?'<i></i>':''}</button></section>`;}
function hallTaskModal(){const tasks=hallTaskData();openModal('日常任务',`<div class="hall-sheet-hero"><b>今日任务</b><span>完成任务，领取社区补给</span></div><div class="hall-task-list">${tasks.map(t=>{const claimed=hallState.tasks.claimed.includes(t.id),pct=Math.min(100,t.current/t.target*100);return `<article class="hall-task-card ${claimed?'claimed':''}"><div class="hall-task-copy"><b>${t.title}</b><small>${t.desc}</small><div class="hall-progress"><i style="width:${pct}%"></i><span>${t.current}/${t.target}</span></div></div><span class="hall-task-reward">${t.reward}</span><button class="btn small" data-action="community-task-claim" data-task="${t.id}" ${claimed||!t.ready?'disabled':''}>${claimed?'已领取':t.ready?'领取':'前往'}</button></article>`}).join('')}</div><p class="modal-text">任务奖励只结算一次，每日刷新；“前往”任务不会自动完成，也不会伪造进度。</p>`);}
function hallStoreTabButton(id,label,iconName,active){return `<button class="hall-store-tab ${active?'active':''}" data-action="community-store-tab" data-tab="${id}" aria-selected="${active}">${icon(iconName)}<span>${label}</span></button>`;}
function hallStoreModal(){const store=hallState.store||{};const tab=store.tab||'packs';const packages=[{id:'free',title:'每日免费礼包',sub:'每日限购1次 · 签到也可领取',items:[['营业金','1,200'],['服饰券','10'],['体力','30']],action:'打开签到',can:!game.state.daily.gift},{id:'inspire',title:'灵感小礼包',sub:'每次限购4次',items:[['服饰券','20'],['体力','10']],action:'180金币',can:game.state.coins>=180},{id:'energy',title:'精力补给包',sub:'每次限购8次',items:[['体力','30'],['服饰券','5']],action:'80服饰券',can:game.state.vouchers>=80},{id:'income',title:'收入加速包',sub:'每次限购10次',items:[['营业金','2,000'],['服饰券','25']],action:'320金币',can:game.state.coins>=320}];const tabs=[['packs','冲榜礼包','gift'],['movie','观影礼盒','book'],['exchange','兑换商店','ticket'],['items','道具栏','work']];const tabsHtml=tabs.map(t=>hallStoreTabButton(t[0],t[1],t[2],tab===t[0])).join('');let panel='';if(tab==='packs'){panel=`<div class="hall-store-section-intro"><span>资源补给</span><b>冲榜礼包</b><small>先补充体力与服饰券，再去工作台完成订单目标。</small></div><div class="hall-store-list">${packages.map(p=>`<article class="hall-store-card"><div class="hall-store-title"><span class="hall-store-title-main">${hallStoreIcon(p.id==='free'?'礼盒':p.title)}<b>${p.title}</b></span><small>${p.sub}</small></div><div class="hall-store-items">${p.items.map(x=>hallItemTile(x[0],x[1])).join('')}</div><button class="btn ${p.id==='free'?'sage':''}" data-action="community-store-buy" data-package="${p.id}" ${p.can?'':'disabled'}>${p.action}</button></article>`).join('')}</div>`;}else if(tab==='movie'){const watched=store.watched===hallDate();panel=`<div class="hall-store-feature hall-movie-gift"><div class="hall-store-feature-icon">${icon('book')}</div><div><small>观影礼盒 · 今日灵感补给</small><h3>看完一段开场影片，领取设计灵感</h3><p>试玩版按一次按钮完成观影记录，奖励会进入当前存档。</p></div><span class="hall-store-feature-badge">${watched?'已领取':'NEW'}</span></div><div class="hall-store-reward-row">${hallItemTile('营业金','+500','reward-coins')}${hallItemTile('服饰券','+15','reward-vouchers')}${hallItemTile('体力','+30','reward-energy')}</div><button class="btn full ${watched?'light':''}" data-action="community-store-watch" ${watched?'disabled':''}>${watched?'今日观影礼盒已领取':'观看并领取礼盒'}</button><p class="modal-text">观影礼盒用于把登录演出和日常经营连接起来，每日可领取一次。</p>`;}else if(tab==='exchange'){const exchanges=[{id:'energy',title:'体力补给',desc:'服饰券换取工作台体力',cost:'40服饰券',reward:'20体力',can:game.state.vouchers>=40&&game.state.energy<100},{id:'vouchers',title:'服饰灵感',desc:'营业金换取服饰券',cost:'1,000营业金',reward:'10服饰券',can:game.state.coins>=1000},{id:'seals',title:'设计印章',desc:'体力换取研发印章',cost:'10体力',reward:'1印章',can:game.state.energy>=10}];panel=`<div class="hall-store-section-intro"><span>资源转换</span><b>兑换商店</b><small>把经营收入转成研发所需的体力、服饰券与印章。</small></div><div class="hall-exchange-list">${exchanges.map(x=>`<article class="hall-exchange-card"><div class="hall-exchange-icon">${hallStoreIcon(x.title)}</div><div><b>${x.title}</b><small>${x.desc}</small><em>消耗 ${x.cost} · 获得 ${x.reward}</em></div><button class="btn small" data-action="community-store-exchange" data-exchange="${x.id}" ${x.can?'':'disabled'}>兑换</button></article>`).join('')}</div>`;}else{const itemDefs=[{id:'energy',title:'灵感体力饮',desc:'工作台体力 +20',icon:'energy'},{id:'materials',title:'订单材料包',desc:'服饰券 +8',icon:'ticket'},{id:'boost',title:'营业加速卡',desc:'营业金 +800',icon:'coin'}];panel=`<div class="hall-store-section-intro"><span>经营道具</span><b>道具栏</b><small>用于短时补给的试玩道具，和工作台、订单、商城经营互相支撑。</small></div><div class="hall-item-list">${itemDefs.map(x=>{const count=Number(store.items?.[x.id]||0);return `<article class="hall-item-card"><div class="hall-store-feature-icon">${icon(x.icon)}</div><div><b>${x.title}</b><small>${x.desc}</small><em>持有 ${count} 个</em></div><button class="btn small" data-action="community-store-use-item" data-item="${x.id}" ${count?'':'disabled'}>${count?'使用':'已用完'}</button></article>`}).join('')}</div>`;}openModal('商店',`<div class="hall-store-head"><b>时尚补给站</b><span>看得见用途的资源规划 · 试玩版不接入真实支付</span></div><div class="hall-store-tabs hall-store-tabs-v36">${tabsHtml}</div><div class="hall-store-panel">${panel}</div>`);}
function hallChatFace(m){if(m.kind==='mine'||m.kind==='look')return `<img src="${model(game.state.profile.avatar)}" data-chat-avatar="profile" alt="${esc(game.state.profile.nickname)}的头像" draggable="false">`;return `<span aria-hidden="true">${m.kind==='system'?'📢':'👤'}</span>`;}
function hallOwnedOutfit(){const s=game.state,rec=s.contest?.records?.[s.contest?.theme],owned=s.owned||[],allowed=[['dress','top','bottom'],['shoes'],['hair','bag','jewelry']];return [0,1,2].map(slot=>{const current=rec?.outfit?.[slot];if(Number.isInteger(current)&&owned.includes(current))return current;return owned.find(id=>allowed[slot].includes(FASHION[id]?.type))??null;});}
function hallChatLookCard(m){const items=(m.outfit||[]).map((id,slot)=>Number.isInteger(id)&&FASHION[id]?`<div class="hall-chat-look-item"><img src="${art(id)}" alt="${esc(FASHION[id].name)}" draggable="false"><small>${esc(FASHION[id].name)}</small></div>`:`<div class="hall-chat-look-item empty"><span>＋</span><small>${['成衣','鞋履','配饰'][slot]}</small></div>`).join('');return `<div class="hall-chat-look-card"><div class="hall-chat-look-head"><b>穿搭日记 · ${esc(m.theme||'今日主题')}</b><span>我的搭配</span></div><div class="hall-chat-look-items">${items}</div><small class="hall-chat-look-note">来自${esc(m.author||game.state.profile.nickname)}的服装穿搭</small></div>`;}
function hallChatMessageBody(m){return m.kind==='look'?hallChatLookCard(m):`<p>${esc(m.text||'')}</p>`;}
function hallChatModal(){const key=hallState.channel;const rows=hallMessageRows(key);openModal('聊天',`<div class="hall-chat-window"><div class="hall-chat-warning">⚠ 社区聊天为本地试玩消息，不连接真实玩家；请勿输入个人敏感信息。</div><div class="hall-chat-list">${rows.map(m=>`<article class="hall-chat-message ${m.kind==='mine'||m.kind==='look'?'mine':''}"><div class="hall-chat-face">${hallChatFace(m)}</div><div><b>${esc(m.author)}</b><small>${esc(m.at||'刚刚')}</small>${hallChatMessageBody(m)}</div></article>`).join('')}</div><div class="hall-chat-compose"><button class="hall-dress-chat" data-action="community-chat-dress" aria-label="发送我的服装穿搭">👗</button><button class="hall-emoji-toggle" data-action="community-chat-emoji" aria-label="打开表情">😊</button><textarea id="hall-chat-input" data-hall-chat-input="${key}" maxlength="40" rows="1" placeholder="点击聊天【${hallChannelLabel(key)}】">${esc(hallState.draft[key]||'')}</textarea><button class="btn" data-action="community-chat-send">发送</button></div>${hallState.emojiOpen?`<div class="hall-emoji-panel">${HALL_EMOJIS.map(x=>`<button data-action="community-chat-emoji-pick" data-emoji="${x}">${x}</button>`).join('')}</div>`:''}<div class="hall-chat-channels">${HALL_CHANNELS.map(x=>`<button data-action="community-chat-channel" data-channel="${x[0]}" class="${key===x[0]?'active':''}">${x[1]}</button>`).join('')}</div></div>`);modal.classList.add('community-chat-modal');setTimeout(()=>{$('#hall-chat-input')?.focus({preventScroll:true});const list=modal.querySelector('.hall-chat-list');if(list)list.scrollTop=list.scrollHeight},0);}
function hallSyncDraft(){const input=$('#hall-chat-input');if(input){hallState.draft[input.dataset.hallChatInput]=input.value;hallSave();}}
function openCurrencyTip(key){
 const tips={
  coins:{name:'经营资金',icon:'coin',uses:'用于店铺升级、拓展、招募员工、版型研发及顾客订单材料费。',sources:'收取营业金（含离线收益）、完成制衣订单，以及领取任务与活动奖励。'},
  energy:{name:'体力',icon:'energy',uses:'用于工作台制作样衣；合并样衣和查看说明不扣体力。',sources:'随时间恢复，也可通过每日补给、任务奖励或商店精力补给包获得。体力上限为100。'},
  vouchers:{name:'服饰券',icon:'ticket',uses:'用于补缺购买已研发版型的服装，也可兑换商店精力补给包。',sources:'完成制衣订单、参与穿搭日记，或领取每日补给及收藏等奖励。'},
  seals:{name:'评选印章',icon:'star',uses:'用于工作台研发高阶服装版型，具体消耗以版型要求为准。',sources:'通过穿搭日记参评、评选里程碑和套装收藏等奖励获得。'}
 };
 const t=tips[key];if(!t)return;
 const amount=game.state[key],balance=key==='energy'?amount+' / 100':fmt(amount);
 openModal(t.name+' · 资源说明',`<section class="currency-tip" aria-label="${t.name}说明"><div class="currency-tip-balance">${icon(t.icon)}<div><small>当前${t.name}</small><b data-currency-balance="${key}">${esc(balance)}</b></div></div><dl class="currency-tip-details"><div><dt>有什么用途</dt><dd>${t.uses}</dd></div><div><dt>如何获取</dt><dd>${t.sources}</dd></div></dl><p class="currency-tip-note">查看说明不会消耗资源，也不会自动领取奖励。</p><button class="btn full" data-action="close">知道了</button></section>`);
}
Object.assign(actions,{
 'community-contest':()=>{ui.communityPage='feed';ui.communityFilter='discover';ui.communityTheme='all';location.hash='contest';ui.view='contest';render();},
 'community-rank':()=>{if(Number(game.state.level)<10)return toast('排行榜将在10级解锁');openModal('街区排行榜',`<div class="hall-rank-hero">✦ 今日穿搭热度榜 ✦</div><div class="hall-rank-list"><div><b>1</b><span>小花的衣橱</span><strong>128赞</strong></div><div><b>2</b><span>周周搭配日记</span><strong>96赞</strong></div><div><b>3</b><span>你的作品</span><strong>${game.state.community.posts.length?'等待互动':'暂未发布'}</strong></div></div><p class="modal-text">示例排行仅用于试玩展示，不代表真实多人榜单。</p>`)},
 'community-market':()=>{if(Number(game.state.level)<20)return toast('市集将在20级解锁');openModal('街区市集',`<div class="hall-market-grid"><button data-action="community-store"><span>服饰补给</span><b>商店</b></button><button data-action="nav" data-view="catalog"><span>我的衣橱</span><b>背包</b></button><button data-action="community-contest"><span>今日主题</span><b>穿搭日记</b></button></div>`)},
 'community-daily':hallTaskModal,'community-store':hallStoreModal,
 'community-task-claim':e=>{const id=e.dataset.task,t=hallTaskData().find(x=>x.id===id);if(!t||!t.ready||hallState.tasks.claimed.includes(id))return;try{t.claim();hallState.tasks.claimed.push(id);hallSave();closeModal();hallTaskModal();toast('任务奖励已领取')}catch(err){toast(err.message)}},
 'community-store-buy':e=>{const id=e.dataset.package;try{if(id==='free'){openSigninModal();return}else if(id==='inspire'){game.tx(s=>{if(s.coins<180)throw new Error('经营资金不足');s.coins-=180;s.vouchers+=20;s.energy=Math.min(100,s.energy+10)})}else if(id==='energy'){game.tx(s=>{if(s.vouchers<80)throw new Error('服饰券不足');s.vouchers-=80;s.energy=Math.min(100,s.energy+30)})}else{game.tx(s=>{if(s.coins<320)throw new Error('经营资金不足');s.coins-=320;s.bank+=2000;s.vouchers+=25})}hallState.store.claimed[id]=(hallState.store.claimed[id]||0)+1;hallSave();hallStoreModal();toast('商店礼包已领取')}catch(err){toast(err.message)}},
 'community-store-tab':e=>{hallState.store.tab=e.dataset.tab||'packs';hallSave();hallStoreModal()},
 'community-store-watch':()=>{if(hallState.store.watched===hallDate())return toast('今日观影礼盒已领取');try{game.tx(s=>{s.coins+=500;s.vouchers+=15;s.energy=Math.min(100,s.energy+30)});hallState.store.watched=hallDate();hallSave();hallStoreModal();toast('观影完成：营业金、服饰券和体力已到账')}catch(err){toast(err.message)}},
 'community-store-exchange':e=>{const id=e.dataset.exchange;const recipes={energy:{costKey:'vouchers',cost:40,rewardKey:'energy',reward:20},vouchers:{costKey:'coins',cost:1000,rewardKey:'vouchers',reward:10},seals:{costKey:'energy',cost:10,rewardKey:'seals',reward:1}};const x=recipes[id];if(!x)return;try{game.tx(s=>{if(s[x.costKey]<x.cost)throw new Error('当前资源不足');if(x.rewardKey==='energy'&&s.energy>=100)throw new Error('体力已满');s[x.costKey]-=x.cost;s[x.rewardKey]+=x.reward});hallSave();hallStoreModal();toast('兑换成功：已补充'+(id==='energy'?'体力':id==='vouchers'?'服饰券':'设计印章'))}catch(err){toast(err.message)}},
 'community-store-use-item':e=>{const id=e.dataset.item;const defs={energy:{rewardKey:'energy',amount:20,label:'灵感体力饮'},materials:{rewardKey:'vouchers',amount:8,label:'订单材料包'},boost:{rewardKey:'coins',amount:800,label:'营业加速卡'}};const x=defs[id];if(!x)return;try{if(!hallState.store.items?.[id])throw new Error('该道具已用完');game.tx(s=>{if(x.rewardKey==='energy'&&s.energy>=100)throw new Error('体力已满');s[x.rewardKey]+=x.amount;});hallState.store.items[id]-=1;hallSave();hallStoreModal();toast(x.label+'已使用')}catch(err){toast(err.message)}},
 'currency-tip':e=>openCurrencyTip(e.dataset.currency),
 'community-help':()=>openModal('社区大厅',`<p class="modal-text">这里是社区与穿搭日记的入口：可以进入今日穿搭日记、浏览作品、点赞收藏评论，也可以在聊天频道发送本地消息。左下角是商场订单，右侧是日常任务和商店。<br>本地试玩不会连接真实玩家，不提供线下交易、充值、买号或跨设备聊天。</p><button class="btn full" data-action="close">知道了</button>`),
 'community-chat':hallChatModal,
 'community-chat-channel':e=>{hallSyncDraft();hallState.channel=e.dataset.channel;hallState.emojiOpen=false;hallSave();hallChatModal()},
 'community-chat-emoji':()=>{hallSyncDraft();hallState.emojiOpen=!hallState.emojiOpen;hallSave();hallChatModal()},
 'community-chat-emoji-pick':e=>{hallSyncDraft();hallState.draft[hallState.channel]=(hallState.draft[hallState.channel]||'')+e.dataset.emoji;hallState.emojiOpen=true;hallSave();hallChatModal()},
 'community-chat-send':()=>{hallSyncDraft();const key=hallState.channel,text=(hallState.draft[key]||'').trim();if(!text)return toast('先写下消息');hallState.messages[key].push({id:'mine-'+Date.now(),author:game.state.profile.nickname,text,kind:'mine',at:'刚刚'});hallState.draft[key]='';hallState.emojiOpen=false;hallSave();hallChatModal();toast('消息已发送到'+hallChannelLabel(key)+'频道')},
 'community-chat-dress':()=>{hallSyncDraft();const key=hallState.channel,s=game.state,theme=THEMES.find(x=>x.id===s.contest?.theme);hallState.messages[key].push({id:'look-'+Date.now(),author:s.profile.nickname,kind:'look',at:'刚刚',theme:theme?.name||'今日主题',outfit:hallOwnedOutfit()});hallState.draft[key]='';hallState.emojiOpen=false;hallSave();hallChatModal();toast('我的服装穿搭已发送')}
});
document.addEventListener('input',e=>{if(e.target.matches('[data-hall-chat-input]')){hallState.draft[e.target.dataset.hallChatInput]=e.target.value;hallSave()}});
window.loopCommunity={state:hallState,save:hallSave,openChat:hallChatModal};

/* V0.15 home editor: video-like decoration flow with real user-provided room and furniture assets. */
