/* V0.32: reliable pointer drag for mobile employee assignment. */
let employeeDrag=null,employeeDragSuppressUntil=0;
function employeeDropTargetAt(x,y){
  const hit=document.elementFromPoint(x,y);
  return hit?.closest?.('.employee-slot-chip:not(:disabled)')||null;
}
function employeeClearDrag(){
  const d=employeeDrag;
  if(!d)return;
  d.card?.classList.remove('employee-dragging');
  try{d.card?.releasePointerCapture?.(d.pointerId)}catch{}
  document.querySelectorAll('.employee-slot-chip.is-drop-target').forEach(el=>el.classList.remove('is-drop-target'));
  employeeDrag=null;
}
function assignEmployeeToDraft(id,shop,slot){
  const d=ui.staffDraft;
  if(!d||d.shop!==Number(shop))return toast('请先打开当前店铺的雇员派驻面板');
  if(!EMP.slotOpen(game.state,Number(shop),Number(slot)))return toast('这个岗位尚未解锁');
  const p=EMP.person(id);
  if(!p||!game.state.employees.owned.includes(id))return toast('请先招募这位雇员');
  d.row=d.row.map(who=>who===id?null:who);
  d.row[Number(slot)]=id;
  ui.staffDraft=d;
  renderEmployeeRoster(Number(shop),Number(slot));
  toast(`${p.name} 已放入${EMP.ROLES[Number(slot)].name}`);
}
document.addEventListener('pointerdown',e=>{
  const card=e.target.closest?.('.employee-person[data-drag-source="employee"]');
  if(!card||!ui.staffDraft||(!e.isPrimary&&e.pointerType!=='mouse'))return;
  if(e.pointerType==='mouse'&&e.button!==0)return;
  employeeDrag={id:card.dataset.employee,shop:ui.staffDraft.shop,pointerId:e.pointerId,startX:e.clientX,startY:e.clientY,moved:false,card};
  card.classList.add('employee-dragging');
  try{card.setPointerCapture?.(e.pointerId)}catch{}
},{capture:true,passive:false});
document.addEventListener('pointermove',e=>{
  const d=employeeDrag;
  if(!d||d.pointerId!==e.pointerId)return;
  if(!d.moved&&Math.hypot(e.clientX-d.startX,e.clientY-d.startY)<6)return;
  d.moved=true;
  if(e.cancelable)e.preventDefault();
  document.querySelectorAll('.employee-slot-chip.is-drop-target').forEach(el=>el.classList.remove('is-drop-target'));
  const target=employeeDropTargetAt(e.clientX,e.clientY);
  if(target)target.classList.add('is-drop-target');
},{capture:true,passive:false});
